import{c as e,n as t,s as n,t as r}from"./reading-catalog-contract-HSvgPmNc.js";var i=Object.freeze({"cinema-with-two-lives":[2,1,0,3,1,1,2],"library-on-the-last-bus":[1,1,2,3,3,0,0],"apples-between-the-blocks":[2,2,1,0,1,3,1],"museum-after-closing-time":[1,2,3,2,3,2,0],"counting-swifts-at-sunset":[2,3,0,3,1,0,2],"engineer-of-second-chances":[0,2,1,2,1,2,3],"joke-that-crossed-a-border":[0,1,3,2,0,2,2],"map-made-of-memories":[1,3,3,2,0,2,0],"month-on-an-imaginary-mars":[2,1,1,0,0,3,1],"who-rides-after-midnight":[0,0,1,3,3,1,2],"lunchroom-as-a-laboratory":[0,2,0,3,3,1,2],"photographs-without-names":[3,0,3,0,2,0,1],"fire-used-with-care":[3,1,1,3,3,0,2],"stage-everyone-can-read":[2,3,3,1,2,0,0],"feed-that-learned-too-well":[2,3,2,1,0,0,3],"crop-below-the-tide":[3,1,2,1,3,0,1],"language-returning-to-airwaves":[3,2,1,0,1,3,1],"weather-written-before-instruments":[0,3,2,1,3,3,0],"journey-home-for-storm-bird":[1,1,0,0,3,0,2],"forest-that-listens-back":[2,3,1,0,0,2,2]});function a({slug:e,title:a,topic:o,genre:s,cefr:c,paragraphs:l,questions:u}){let d=`${r}.task12_18.${e}`,f=i[e];if(!Array.isArray(f)||f.length!==u.length)throw TypeError(`${d}: answer position schedule must match the question count`);let p={id:d,revision:1,kind:`task12_18`,title:a,topic:o,genre:s,cefr:c,provenance:`original`,validation:{contract:t},task:{text:l.join(`

`),questions:u.map(([e,t,n,r,i,a],o)=>{let s=f[o],c=n.slice(),[l]=c.splice(r,1);return c.splice(s,0,l),{id:`${d}.q${o+1}`,type:e,prompt:t,options:c,answer:s,evidence:{quote:i,explanationRu:a}}})}};return n(p),p}var o=e([a({slug:`cinema-with-two-lives`,title:`The cinema with two lives`,topic:`community-cinema-restoration`,genre:`local-history-feature`,cefr:`B1`,paragraphs:[`The Star Cinema stood empty at the end of Market Street for almost fifteen years. Older residents remembered Saturday films there, but younger people knew it only as a building with boards across the doors. When a supermarket company offered to buy the site, most people expected the cinema to disappear. Then history teacher Nina Cole asked the council for three months to test another idea.`,`Nina did not begin by promising to restore everything. The roof leaked, many seats were broken, and the heating system belonged to another century. Instead, she invited residents to clean one safe room beside the entrance. They displayed old tickets and photographs borrowed from local families. More than six hundred visitors came during the first two weekends, proving that interest in the place was not simply Nina’s private dream.`,`The visitors also left written suggestions. Some wanted the largest screen and expensive new equipment immediately. Others asked for rehearsal space, afternoon clubs and cheap family events. Nina’s group studied the comments and chose a mixed plan. The main hall would show films on three evenings, while smaller rooms could host school projects and community meetings during the day. This wider use made grants easier to obtain.`,`Money was still a problem, so the volunteers divided the work into stages. Local builders repaired the roof first, and college students designed simple signs. Nobody tried to copy the cinema exactly as it had looked in 1952. The team kept the curved ticket desk because people loved it, but added a lift and wider doors. Nina called this approach “keeping the memory, not the inconvenience.”`,`The first public film night was less perfect than the posters suggested. A new projector stopped for twelve minutes, and rain made a loud sound on the repaired metal roof. Yet no one left. An electrician in the audience found the loose cable, while café volunteers gave out tea. The interruption became part of the story people told afterwards, not evidence that the whole project had failed.`,`Today the Star has a small paid staff, although volunteers still choose part of the programme. Ticket income covers ordinary running costs, and room hire pays for free workshops. The cinema does not compete with the large modern complex outside town, which offers more screens and softer seats. Its strength is different: people can propose an event and see neighbours turn that suggestion into a real evening.`,`Nina now receives messages from groups hoping to save other old buildings. She warns them that affection is not a business plan. A successful project needs evidence of demand, several possible uses and patient decisions about what to preserve. Even so, she believes an empty building can become useful again when a community is invited to shape its next chapter rather than merely admire its past.`],questions:[[`detail`,`Why did Nina ask the council for three months?`,[`To test whether residents supported another use for the cinema`,`To prepare the site for the supermarket company’s arrival`,`To move her history classes into the empty main hall`,`To discover who had damaged the cinema heating system`],0,`Then history teacher Nina Cole asked the council for three months to test another idea.`,`Слова цитаты показывают, что Нина просила время для проверки альтернативной идеи, а не для продажи или школьного переезда.`],[`inference`,`What did the first exhibition demonstrate?`,[`The old photographs were valuable enough to fund all repairs`,`Public interest extended beyond the organiser herself`,`Most visitors wanted the building returned exactly to 1952`,`The entrance room could already operate as a full cinema`],1,`More than six hundred visitors came during the first two weekends, proving that interest in the place was not simply Nina’s private dream.`,`Фрагмент прямо показывает широкий интерес посетителей и тем самым подтверждает, что проект поддерживала не только сама Нина.`],[`purpose-attitude`,`Why does the writer mention different suggestions from visitors?`,[`To show that residents refused to attend evening films`,`To argue that public consultations usually delay useful work`,`To explain how the building gained several complementary functions`,`To prove that school projects brought the greatest income`],2,`Nina’s group studied the comments and chose a mixed plan.`,`Предложение о смешанном плане показывает итог разных предложений: кино, занятия и встречи должны были сосуществовать в здании.`],[`reference`,`What does “this approach” in paragraph 4 refer to?`,[`Repairing only the roof with help from local builders`,`Replacing historic features with exact modern copies`,`Waiting until every part could be restored at once`,`Combining selected memories with present-day accessibility`],3,`The team kept the curved ticket desk because people loved it, but added a lift and wider doors.`,`Формулировка перед местоимением показывает сочетание сохранённой стойки с новыми доступными входами, на которое и указывает this approach.`],[`vocabulary-context`,`What does “stages” most nearly mean in paragraph 4?`,[`Separate steps completed over time`,`Raised platforms used for performances`,`Historical periods shown in photographs`,`Groups competing for the same grant`],0,`Money was still a problem, so the volunteers divided the work into stages.`,`Слова о разделении работы показывают, что stages означает последовательные этапы ремонта, а не театральные площадки.`],[`main-idea`,`Which statement best describes the Star Cinema today?`,[`It succeeds mainly by offering more comfort than a modern complex`,`It is financially practical because the community uses it in several ways`,`It depends entirely on unpaid workers and occasional donations`,`It shows only films selected by the original restoration group`],1,`Ticket income covers ordinary running costs, and room hire pays for free workshops.`,`Цитата показывает устойчивую модель из разных доходов и видов деятельности, подтверждая практичность многоцелевого общественного пространства.`],[`detail`,`What warning does Nina give other groups?`,[`Historic buildings should never be changed for modern users`,`Councils will support a project only after a supermarket bid`,`Warm feelings must be supported by demand and a workable plan`,`Volunteer projects should avoid employing any permanent staff`],2,`She warns them that affection is not a business plan.`,`Слова цитаты показывают ограниченность одной любви к зданию; далее Нина указывает на спрос, функции и продуманные решения.`]]}),a({slug:`library-on-the-last-bus`,title:`The library on the last bus`,topic:`mobile-library-service`,genre:`librarian-interview`,cefr:`B1`,paragraphs:[`When the branch library in three hill villages closed, librarian Aaron Blake expected readers to travel to the town. Few did. The only regular bus left each village before many pupils finished school, and older residents found the forty-minute journey tiring. Aaron suggested using a retired city bus as a travelling library. At first, even his manager thought the plan sounded more charming than useful.`,`The team spent a month asking residents what they would actually borrow. Children requested adventure stories and graphic novels, while adults mentioned gardening guides, crime fiction and large-print books. More surprisingly, many people wanted help with online forms. The survey changed the design: one row of seats remained, but the back of the bus gained a desk, a printer and a reliable internet connection.`,`Driving a library is different from parking one. Narrow winter roads made a fixed weekly timetable impossible, so the team publishes arrival windows rather than exact minutes. A text message is sent when the bus leaves the previous stop. Aaron says this small change matters because people no longer wait outside in cold weather for a vehicle delayed by sheep, snow or road repairs.`,`The bus carries only about eight hundred books, far fewer than the town building. However, every borrower can order from the full county collection. Requested books travel in labelled boxes and usually arrive the following week. Returns can be left at any village stop. Aaron deliberately changes the visible shelves often, since a small collection feels larger when regular visitors discover unfamiliar titles instead of seeing the same covers for months.`,`One Tuesday, twelve-year-old Leah arrived with a broken model bridge from a science project. She did not need a book; she needed to print a stronger design sent by her teacher. Aaron helped her download the file and showed her how to check its measurements. That visit persuaded the team to describe the service as “a library that moves,” not simply “books on wheels.”`,`The travelling library has also become a meeting point, although Aaron protects its quiet purpose. Residents may exchange local notices beside the door, but political meetings and sales are not allowed inside. He wants everyone to feel welcome without believing they must join a group or buy something. For some visitors, a brief conversation with the driver is enough social contact for the day.`,`After two years, borrowing in the villages is higher than it was before the branches closed, but Aaron does not call the closures a good decision. The bus cannot provide warm study rooms, long opening hours or shelves people can browse at any time. It is a thoughtful answer to distance, not a complete replacement for a permanent public building.`],questions:[[`detail`,`Why had few village residents used the town library?`,[`Membership fees had increased after the local branches closed`,`The town collection contained mostly specialist adult books`,`Residents were not informed where the town library stood`,`Transport timing and the journey created practical difficulties`],3,`The only regular bus left each village before many pupils finished school, and older residents found the forty-minute journey tiring.`,`Цитата показывает две транспортные трудности: неудобное расписание для школьников и утомительную поездку для пожилых жителей.`],[`inference`,`How did the survey affect the bus conversion?`,[`It added digital support alongside the planned book service`,`It persuaded the county to reopen one village branch`,`It replaced adult books with children’s graphic novels`,`It showed that residents preferred exact arrival times`],0,`The survey changed the design: one row of seats remained, but the back of the bus gained a desk, a printer and a reliable internet connection.`,`Фрагмент показывает, что ответы жителей привели к рабочему месту, принтеру и интернету, то есть расширили услугу цифровой помощью.`],[`purpose-attitude`,`Why does Aaron’s team give an arrival window and send a text?`,[`To let the driver choose which village to visit each week`,`To reduce uncomfortable waiting when road conditions cause delays`,`To prevent too many borrowers entering the vehicle together`,`To advertise newly arrived books before every stop`],1,`people no longer wait outside in cold weather for a vehicle delayed by sheep, snow or road repairs.`,`Слова цитаты показывают практическую цель уведомления: люди не стоят на холоде из-за непредсказуемых дорожных задержек.`],[`reference`,`What does “the full county collection” refer to?`,[`All eight hundred books currently carried on the bus`,`The private collections donated by hill residents`,`Books held across the wider public library system`,`Digital files stored on the bus computer`],2,`However, every borrower can order from the full county collection.`,`Формулировка order from показывает доступ к более широкому фонду библиотечной системы, а не только к книгам внутри автобуса.`],[`vocabulary-context`,`What does “browse” mean in the final paragraph?`,[`Repair damaged books before returning them`,`Reserve a seat for a long study session`,`Search the internet through a public printer`,`Look through available books without a fixed choice`],3,`The bus cannot provide warm study rooms, long opening hours or shelves people can browse at any time.`,`Слова shelves и at any time показывают, что browse означает свободно рассматривать доступные книги без заранее выбранного заказа.`],[`main-idea`,`What is the main strength of the mobile library?`,[`It adapts a limited vehicle to several real local needs`,`It offers more space and longer hours than former branches`,`It provides a formal meeting room for village organisations`,`It carries the entire county collection on every journey`],0,`She did not need a book; she needed to print a stronger design sent by her teacher.`,`Этот фрагмент показывает гибкость услуги на конкретном примере: мобильная библиотека решает образовательную задачу не только выдачей книг.`],[`inference`,`What is Aaron’s view of the closed branches?`,[`Their closure was justified because village borrowing later rose`,`The mobile service helps but does not replace everything they offered`,`Their study rooms were rarely used by local residents`,`The county should replace them with larger travelling buses`],1,`It is a thoughtful answer to distance, not a complete replacement for a permanent public building.`,`Заключительная формулировка прямо показывает сдержанную оценку Аарона: автобус полезен, но не восполняет все функции постоянной библиотеки.`]]}),a({slug:`apples-between-the-blocks`,title:`Apples between the blocks`,topic:`urban-community-orchard`,genre:`neighbourhood-project-report`,cefr:`B1`,paragraphs:[`Between two blocks of flats lay a piece of grass that nobody used except as a shortcut. The soil was thin, and footballs often rolled into the road. When resident Farah Aziz proposed a small orchard, neighbours imagined rows of trees and free apples. The reality began with less exciting work: checking underground pipes, testing the soil and asking who would water young trees in August.`,`A gardening charity advised the group to plant only twelve trees in the first year. This disappointed people who wanted an instant transformation, but the smaller number allowed volunteers to learn. They selected apple, pear and plum varieties that flowered at different times. If late frost damaged one group, another might still produce fruit. The plan valued reliability over an impressive opening photograph.`,`The organisers also refused to divide the orchard into private plots. Instead, each Saturday team cares for every tree on a rotating list. A family may miss several weeks without losing access to the harvest. Farah says shared responsibility is slower to organise, yet it prevents the strongest gardeners from receiving all the good space while beginners stand at the edge.`,`During the first summer, watering cans disappeared twice and one tree was damaged by a bicycle. The group responded with a low wooden border and a locked box for tools, but it did not put up a tall fence. A wide entrance and a path through the orchard kept the old shortcut open. Signs explain why young roots need protection without presenting passers-by as intruders. People were asked to move carefully, not to stop crossing the space.`,`The first real harvest produced far more plums than the residents could eat. Volunteers placed a table by the entrance with paper bags and a sign inviting people to take some. They also held a cooking afternoon where neighbours compared jam recipes. Fruit that was bruised but safe went into sauce, while rotten pieces were collected separately for compost.`,`Not every result can be counted in kilograms. Children now recognise when each tree blossoms, and several adults who had never spoken discovered that they share family recipes. Informal conversations continue beyond gardening days. At the same time, disagreements have not vanished. Residents still debate noisy Saturday work and whether fallen fruit is cleared quickly enough. The monthly meeting exists partly to handle these ordinary tensions.`,`Four years later, the orchard remains small. Its success comes from staying manageable rather than expanding across every empty lawn. The group has published its watering rota, soil results and yearly mistakes online for other neighbourhoods. Farah hopes people will copy the careful questions behind the project, not simply order twelve identical trees and expect a community to appear beneath them.`],questions:[[`detail`,`What did the orchard project do before planting?`,[`It built a fence around the entire shortcut`,`It invited a company to sell fruit locally`,`It investigated the site and future watering arrangements`,`It gave permanent plots to experienced gardeners`],2,`checking underground pipes, testing the soil and asking who would water young trees in August.`,`Перечисленные в цитате действия показывают предварительную проверку участка и организацию ухода до посадки деревьев.`],[`inference`,`Why were different fruit varieties selected?`,[`To ensure the orchard looked fully grown in its first photograph`,`To make every type of fruit ready on the same weekend`,`To avoid asking the gardening charity for further advice`,`To reduce the risk that one weather event ruined the whole crop`],3,`If late frost damaged one group, another might still produce fruit.`,`Условное предложение показывает распределение риска: разные сроки цветения оставляют урожай, даже если мороз повредит часть деревьев.`],[`purpose-attitude`,`What is Farah’s reason for shared rather than private care?`,[`It keeps participation fair for people with different experience and time`,`It allows the strongest gardeners to choose the best trees first`,`It removes the need for a weekly schedule of practical tasks`,`It guarantees that every family collects an equal fruit weight`],0,`it prevents the strongest gardeners from receiving all the good space while beginners stand at the edge.`,`Слова цитаты показывают цель общего ухода: не допустить неравного распределения пространства между опытными и начинающими участниками.`],[`reference`,`What does “the old shortcut” refer to?`,[`A narrow road used by delivery bicycles`,`The route people already took across the grass`,`A path connecting the orchard with the charity office`,`The entrance created for moving gardening tools`],1,`A wide entrance and a path through the orchard kept the old shortcut open.`,`Формулировка kept open указывает на прежний проход жителей через газон, который проект сохранил внутри сада.`],[`vocabulary-context`,`What does “bruised” mean when describing the fruit?`,[`Picked before it had become fully ripe`,`Mixed with several different plum varieties`,`Slightly damaged but still fit for cooking`,`Covered with soil from the compost container`],2,`Fruit that was bruised but safe went into sauce, while rotten pieces were collected separately for compost.`,`Противопоставление safe и rotten показывает, что bruised означает помятые, но ещё пригодные для приготовления плоды.`],[`main-idea`,`Which outcome does the writer treat as part of the project’s success?`,[`The complete disappearance of disagreements among neighbours`,`The rapid expansion of orchards onto all nearby lawns`,`The sale of enough fruit to finance new apartment repairs`,`New knowledge and relationships alongside a modest harvest`],3,`Children now recognise when each tree blossoms, and several adults who had never spoken discovered that they share family recipes.`,`Цитата показывает два нематериальных результата — знания детей и новые связи взрослых, дополняющие количество собранных фруктов.`],[`inference`,`What does Farah want other neighbourhoods to copy?`,[`Careful planning and honest learning from mistakes`,`The exact number and varieties of the original trees`,`The rule that every unused lawn needs an orchard`,`The design of the locked wooden box for tools`],0,`Farah hopes people will copy the careful questions behind the project, not simply order twelve identical trees`,`Слова not simply противопоставляют механическое повторение посадки вдумчивым вопросам, показывая желаемый перенос процесса и опыта.`]]}),a({slug:`museum-after-closing-time`,title:`The museum after closing time`,topic:`teen-museum-guides`,genre:`first-person-learning-narrative`,cefr:`B1`,paragraphs:[`I joined the city museum’s teenage guide programme because I liked history and wanted something useful for my college application. I imagined memorising dates and leading polite visitors past glass cases. On our first evening, however, curator Mr Lee gave us a wooden kitchen tool without a label. He asked us to invent three possible uses and defend each guess before he told us what it was.`,`The object was a butter mould, but the guessing mattered more than the answer. Mr Lee explained that visitors pay closer attention after they have formed a question of their own. He warned us not to turn every tour into a quiz with winners and losers. A guide should make uncertainty feel safe, then connect people’s observations to reliable information about the object.`,`My first practice tour went badly. I spoke so quickly that the group could not examine anything, and I used the phrase “as you can clearly see” twice. Another trainee, Rosa, later pointed out that nothing is clear to everybody. A visitor may have limited sight, stand at a different angle or simply notice another detail. I replaced the phrase with specific descriptions and longer pauses.`,`We also learned to choose fewer stories. The old tour script included twelve rooms and nearly fifty objects in one hour. Instead of racing through it, each trainee created a route around six connected items. Mine followed the changing ways families stored food. A clay jar, an ice box and an early electric fridge became parts of one question rather than separate facts.`,`The real test came during an evening for families. A little boy asked why the museum kept ordinary broken cups when castles and swords seemed more important. I showed him a cup repaired with metal staples and explained that its owner had valued it enough to mend. His question changed my final stop: I began asking what everyday object visitors themselves would choose to preserve.`,`Not every visitor wanted to speak, so I stopped expecting an answer from each person. Some people listened while others talked; one family wrote a response on the museum’s comment card after leaving. Mr Lee said participation can be visible, quiet or delayed. The important thing is to offer several doors into a story without pulling anyone through one of them.`,`By the end of the programme, I knew fewer dates than the old script contained, yet I understood the collection more deeply. I had learned to observe, describe and admit when a question required checking. The experience will still appear on my college application, but that is no longer its main value. Now, when I enter any museum, I look for the choices behind the display and the missing voices around it.`],questions:[[`detail`,`What happened during the trainees’ first evening?`,[`They practised giving a complete tour through twelve rooms`,`They proposed possible purposes for an unlabelled object`,`They repaired an old cup using traditional metal staples`,`They wrote object labels for a family exhibition`],1,`He asked us to invent three possible uses and defend each guess before he told us what it was.`,`Цитата показывает первое упражнение: подростки предлагали и обосновывали возможные функции предмета до получения ответа.`],[`inference`,`Why did Mr Lee value the guessing activity?`,[`It helped him select the most knowledgeable trainee immediately`,`It allowed the museum to avoid researching difficult objects`,`It encouraged visitors to become curious before hearing established facts`,`It made competitive quizzes the main feature of every tour`],2,`visitors pay closer attention after they have formed a question of their own.`,`Слова цитаты показывают связь собственного вопроса с более внимательным восприятием последующей достоверной информации.`],[`purpose-attitude`,`Why does the narrator mention the phrase “as you can clearly see”?`,[`To suggest that guides should avoid describing visible details`,`To demonstrate that Rosa could see every museum object better`,`To explain why the practice group needed brighter room lighting`,`To show feedback exposed an excluding assumption`],3,`Another trainee, Rosa, later pointed out that nothing is clear to everybody.`,`Фрагмент показывает критику скрытого предположения о восприятии всех людей и объясняет последующее изменение речи рассказчицы.`],[`reference`,`What does “it” in “Instead of racing through it” refer to?`,[`The old tour containing many rooms and objects`,`The programme application completed before college`,`The evening event organised for young families`,`The route about changing methods of food storage`],0,`The old tour script included twelve rooms and nearly fifty objects in one hour. Instead of racing through it`,`Предыдущее предложение называет старый насыщенный маршрут, поэтому местоимение it указывает именно на него.`],[`vocabulary-context`,`What does “stops” mean in the description of the tour?`,[`Moments when visitors were required to remain silent`,`Selected points where the guide discussed particular objects`,`Museum rooms closed because the programme ran late`,`Questions that the curator refused to answer publicly`],1,`His question changed my final stop: I began asking what everyday object visitors themselves would choose to preserve.`,`Слова final stop и began asking показывают отдельную смысловую точку экскурсии у выбранного предмета, а не закрытую комнату.`],[`main-idea`,`What teaching principle develops through the programme?`,[`A successful guide should provide as many dates as possible`,`Every visitor must answer aloud to prove active participation`,`Connected stories and open questions can deepen attention`,`Teenage guides should replace curators at family events`],2,`The important thing is to offer several doors into a story without pulling anyone through one of them.`,`Образ нескольких входов в историю показывает принцип добровольного и разнообразного участия, поддерживаемого вопросами и связным рассказом.`],[`inference`,`How has the narrator’s motivation changed by the end?`,[`She now wants only to improve the old museum script`,`She has decided that college applications have no value`,`She prefers collecting objects to speaking with visitors`,`She values a new way of examining museums beyond its practical benefit`],3,`The experience will still appear on my college application, but that is no longer its main value.`,`Противопоставление в цитате показывает, что практическая запись для колледжа сохранилась, но главным стало новое понимание музеев.`]]}),a({slug:`counting-swifts-at-sunset`,title:`Counting swifts at sunset`,topic:`urban-bird-citizen-science`,genre:`popular-science-field-report`,cefr:`B2`,paragraphs:[`Every May, swifts return to Northbridge and spend the evenings racing above its roofs. For years, residents treated their sharp calls as a familiar sign of summer. Then birdwatcher Elise Morgan noticed that several streets had become strangely quiet. Individual memories differed about when the change had begun. There was no reliable local record showing whether the birds were truly declining, so she designed a survey that ordinary residents could repeat without climbing to nests or handling wildlife.`,`Volunteers received a map divided into short street sections and were asked to stand at the same point for twenty minutes before sunset. Dates were limited to comparable weeks in the breeding season. They counted birds entering holes beneath roofs, not every swift flying overhead. This distinction mattered because a feeding group might cross several survey areas and be counted repeatedly, whereas an entry into a roof offered stronger evidence that a nest site was being used.`,`The first summer produced an untidy set of results. Some observers recorded a zero because they had arrived after rain, when the birds fed far away. Others confused swifts with swallows. Blank forms were kept separate from genuine zero counts. Rather than remove all doubtful entries, Elise marked their confidence level and organised evening walks where beginners compared wing shape and flight. The following year, agreement between neighbouring observers improved substantially.`,`When the two years were mapped, the quietest areas shared an unexpected feature: many older buildings had recently received new roofs. The work had not deliberately harmed birds; contractors had simply sealed narrow openings to improve insulation. Building age alone did not explain the pattern, because unrenovated roofs nearby still held nests. A housing association offered to test special nesting bricks during its next renovation. These hollow units maintained the building’s weather protection while leaving a small internal chamber accessible from outside.`,`Elise resisted announcing success as soon as birds flew near the new bricks. Swifts often inspect several openings without nesting, so the team waited for repeated entries carrying feathers or food. The volunteers avoided shining lights inside or playing calls that might alter behaviour. By the fourth season, cameras placed well below the entrances confirmed chicks at nine renovated buildings. The result was encouraging, though it did not prove that the same design would work on every wall or in every district.`,`The survey also established a baseline for future decisions. It cannot count every bird, and volunteers still miss activity behind private courtyards. Observation dates and weather are published beside the totals. However, the same limited method applied each year can reveal direction even when the total is incomplete. If a street loses several occupied sites after construction, planners now have evidence for investigating the change rather than relying on a general memory that there once seemed to be more birds.`,`Northbridge’s project did not turn residents into professional ecologists. It gave them a precise role in a longer chain: observing consistently, recording uncertainty and making the results available to specialists and builders. Contractors began consulting the map before scaffolding went up. The most valuable outcome may be the conversation created between groups that once met only during conflict. Roofs can conserve heat and still provide nesting spaces, but that compromise becomes possible only when hidden wildlife is noticed before renovation begins.`],questions:[[`detail`,`What were volunteers instructed to count?`,[`Swifts entering openings beneath particular roofs`,`Every bird crossing the evening survey map`,`Empty chambers discovered during roof repairs`,`Calls heard from inside private courtyards`],0,`They counted birds entering holes beneath roofs, not every swift flying overhead.`,`Слова цитаты показывают точную единицу наблюдения — вход птицы под крышу, а не любой полёт над участком.`],[`inference`,`Why was counting all flying swifts considered unreliable?`,[`Their calls could not be heard before sunset`,`The same feeding birds could pass through multiple areas`,`Most residents could observe only from upper floors`,`Rain caused the birds to enter buildings repeatedly`],1,`a feeding group might cross several survey areas and be counted repeatedly`,`Фрагмент показывает риск повторного учёта одной группы в разных местах, подтверждая ненадёжность подсчёта всех пролетающих птиц.`],[`purpose-attitude`,`How did Elise respond to uncertain first-year observations?`,[`She published them as equally reliable to avoid discouraging beginners`,`She replaced them with estimates from professional birdwatchers`,`She preserved their limitations and improved volunteer identification skills`,`She restricted later surveys to streets unaffected by rain`],2,`Rather than remove all doubtful entries, Elise marked their confidence level and organised evening walks`,`Формулировка rather than показывает, что Элиз сохранила сомнительные данные с отметкой уверенности и одновременно улучшила подготовку наблюдателей.`],[`reference`,`What does “These hollow units” refer to?`,[`The sealed openings found in recently insulated roofs`,`The cameras positioned below active nest entrances`,`The street sections assigned to resident observers`,`The special bricks containing a nesting chamber`],3,`A housing association offered to test special nesting bricks during its next renovation. These hollow units`,`Предыдущее предложение называет специальные гнездовые кирпичи, поэтому слова These hollow units указывают именно на них.`],[`vocabulary-context`,`What is a “baseline” in paragraph 6?`,[`An initial reference against which later change can be judged`,`A legal minimum number of nests for each building`,`A route running underneath the surveyed rooftops`,`A complete count produced without missing any birds`],0,`The survey also established a baseline for future decisions.`,`Слова for future decisions показывают, что baseline — это исходная точка сравнения для последующих наблюдений и решений.`],[`main-idea`,`Which claim best captures the project’s method?`,[`Large totals matter more than consistent observation rules`,`Limited repeated evidence can guide practical cooperation`,`Volunteer records should replace specialist ecological research`,`Modern insulation is incompatible with urban bird conservation`],1,`the same limited method applied each year can reveal direction even when the total is incomplete.`,`Цитата показывает главную ценность повторяемого ограниченного метода: он обнаруживает направление изменений и поддерживает практические совместные решения.`],[`inference`,`Why did the team wait before declaring the nesting bricks successful?`,[`The housing association had not completed its insulation tests`,`The cameras were likely to frighten all adult birds away`,`Checking an opening did not prove birds nested there`,`The first volunteers had counted swallows instead of swifts`],2,`Swifts often inspect several openings without nesting, so the team waited for repeated entries carrying feathers or food.`,`Слова without nesting показывают, что одиночный осмотр отверстия не доказывал гнездование; требовались повторные признаки использования.`]]}),a({slug:`engineer-of-second-chances`,title:`The engineer of second chances`,topic:`repair-engineering-career`,genre:`biographical-profile`,cefr:`B2`,paragraphs:[`As a child, Mara Chen was famous in her family for taking clocks apart and less famous for putting them back together. Her interest became serious when a neighbour gave her a broken cassette player. An electronics shop had called it uneconomical to repair, but the neighbour allowed Mara to experiment. She borrowed a basic meter and learned to trace the circuit from a library manual. After several evenings, she found a cracked solder joint that cost almost nothing to fix. The player lasted another decade.`,`At university Mara studied product engineering, a field that often celebrates new inventions. She was more interested in what happened after products left the drawing board. A sealed battery, an unusual screw or missing manual could turn a minor fault into the end of an otherwise useful device. She interviewed owners as well as technicians, since difficulty begins before a tool touches the case. For her final project, she compared three lamps that looked similar but required completely different levels of effort to open and diagnose.`,`Her first job was at a company making kitchen equipment. Mara persuaded colleagues to invite repair technicians to early design meetings. The technicians noticed details laboratory tests had missed: grease covered tiny labels, frequently opened clips became weak, and replacement parts arrived without clear orientation marks. Production engineers initially worried that the meetings would delay launch. None of these problems made a new machine fail in a demonstration, yet each could make routine maintenance slower and more expensive.`,`Mara later created a small consultancy that measures “repair friction.” Her team records how long trained and first-time users need to reach a common component, what information they require and whether the product can be closed safely again. Observers note wrong turns instead of quietly guiding participants past them. A quick opening is not always the goal; electrical protection may demand extra steps. The aim is to ensure that each barrier has a safety reason rather than merely hiding how the object was assembled.`,`One client resisted publishing parts diagrams because managers feared cheaper copies. Mara proposed releasing only the information needed for diagnosis and replacement. Independent workshops then reported faults using the same component names as the manufacturer. Within a year, those reports revealed a weak pump seal. Changing one inexpensive piece reduced warranty claims, so openness provided the company with useful field evidence as well as helping repairers.`,`Mara also volunteers at monthly repair sessions, but she refuses the heroic image of an expert rescuing objects from helpless owners. She places the tools between herself and the visitor, explains the risk and asks what they observe. Owners leave with notes about the diagnosis even when no repair follows. Sometimes the safest conclusion is that an item should not be repaired. Success can mean identifying a dangerous fault clearly, not forcing every object back into service.`,`Now policymakers often ask Mara whether laws should require repairable products. She supports access to parts and information, yet warns that a single score can oversimplify design. A waterproof medical device and a desk fan face different risks. Public measures should reveal assumptions about the expected user and repair task. Her career has taught her to ask a more useful question than “Can this be opened?”: who needs to open it, for what task, with which knowledge, and what should remain protected?`],questions:[[`detail`,`What first showed Mara that repair could be worthwhile?`,[`A university comparison of three modern lamps`,`A workshop report about a weak pump seal`,`A clock she successfully rebuilt for her family`,`A cassette player restored by fixing one cheap fault`],3,`she found a cracked solder joint that cost almost nothing to fix. The player lasted another decade.`,`Цитата показывает дешёвую конкретную неисправность и долгую последующую работу проигрывателя, подтверждая ценность ремонта.`],[`inference`,`What concerned Mara during her university studies?`,[`Design choices could make ordinary faults unnecessarily terminal`,`New products received too little attention from engineering students`,`Similar-looking lamps were becoming impossible to manufacture`,`Electronics shops lacked equipment for testing cassette players`],0,`A sealed battery, an unusual screw or missing manual could turn a minor fault into the end of an otherwise useful device.`,`Перечисленные препятствия показывают тревогу Мары: конструкция превращала небольшую неисправность в преждевременный конец полезного устройства.`],[`purpose-attitude`,`Why were repair technicians invited into early design meetings?`,[`To train engineers to perform faster product demonstrations`,`To identify maintenance problems that laboratory testing overlooked`,`To persuade customers to buy official replacement machines`,`To decide which kitchen equipment needed waterproof cases`],1,`The technicians noticed details laboratory tests had missed`,`Краткая формулировка прямо показывает цель участия техников: их практический опыт раскрывал проблемы обслуживания, незаметные лабораторным испытаниям.`],[`reference`,`What does “each barrier” refer to in paragraph 4?`,[`Every difference between trained and first-time users`,`Every component included in a repair-friction report`,`Every step or obstacle that makes access harder`,`Every safety law proposed by national policymakers`],2,`The aim is to ensure that each barrier has a safety reason rather than merely hiding how the object was assembled.`,`Слова safety reason показывают, что each barrier означает препятствие или дополнительный шаг при доступе к детали.`],[`vocabulary-context`,`What does “field evidence” mean in paragraph 5?`,[`Measurements collected on agricultural equipment outdoors`,`Legal documents submitted during a warranty dispute`,`Diagrams produced before a product reaches customers`,`Information arising from products used and repaired in practice`],3,`Independent workshops then reported faults using the same component names as the manufacturer.`,`Предложение о сообщениях мастерских показывает, что field evidence — практические данные о неисправностях реальных используемых устройств.`],[`main-idea`,`Which principle most consistently guides Mara’s work?`,[`Repair access should be purposeful, informed and safe`,`Every broken product deserves to be returned to service`,`Manufacturers should publish every confidential design detail`,`Fast opening is the best measure of engineering quality`],0,`A quick opening is not always the goal; electrical protection may demand extra steps.`,`Цитата исключает простую скорость как универсальную цель и показывает баланс доступности ремонта с обоснованной безопасностью.`],[`inference`,`Why does Mara distrust one universal repair score?`,[`Consumers would use it to compare products from different companies`,`Different products require different safety trade-offs`,`Repair technicians cannot agree on common component names`,`Policymakers refuse to include replacement parts in legislation`],1,`A waterproof medical device and a desk fan face different risks.`,`Сопоставление двух устройств показывает разные риски и подтверждает, что единая оценка может скрыть важные различия назначения.`]]}),a({slug:`joke-that-crossed-a-border`,title:`The joke that crossed a border`,topic:`video-game-localisation`,genre:`digital-culture-essay`,cefr:`B2`,paragraphs:[`When players discuss translated video games, they often ask whether every word matches the original. For localisation editor Gabriel Soto, that question is only the beginning. A game is not a page of text: dialogue must fit buttons, character movement, recorded timing and choices the player may make in a different order. Players may also return to a line after discovering information that changes its tone. A literal sentence can be accurate in isolation and still fail inside the moving system that gives it meaning.`,`Gabriel remembers a comic scene in which a nervous guard used a proverb about carrying water in a basket. The image was familiar and amusing in the source language but meaningless to most target players. Footnotes were impossible during the fast exchange. Replacing it with a local proverb would have suggested the fictional guard came from a real modern country. The team instead wrote a new joke about a leaking helmet, using an object already visible in the scene.`,`The new line preserved neither the basket nor the original wording, which worried one translator. The editor returned to the scene’s function: the guard was trying to sound wise and accidentally revealing his fear. Test players laughed at the helmet line and understood his character. A second group played the scene without being told that a joke had changed. Gabriel recorded the change in a shared note, explaining what had been altered and which dramatic effect the team intended to keep.`,`Space creates another kind of problem. A menu button designed around a short English command may not hold a longer phrase in another language. Shrinking the letters can make them unreadable, while cutting the translation may remove essential meaning. Screen readers may also pronounce an unexplained abbreviation badly. Good localisation therefore begins before the final interface is locked. Designers can allow flexible boxes, and writers can see their lines in context instead of delivering a spreadsheet that hides the screen.`,`Voice recording makes these choices audible. An actor cannot extend a warning for four extra seconds if the animated door closes halfway through it. Sometimes engineers adjust the scene; sometimes the translator finds a shorter rhythm. Lip movement may matter in a close view but disappear in a distant one. Gabriel dislikes the phrase “making the language fit,” because it sounds as if language alone must surrender. In the best projects, code, animation and words all move slightly towards one another.`,`Cultural references require similar restraint. Removing every unfamiliar detail would flatten the invented world, yet leaving a crucial clue unexplained can block progress. Gabriel asks whether confusion is intentional. Playtesting records where hesitation creates curiosity and where it ends a session. A mysterious festival name may invite discovery, while an untranslated instruction may merely punish the player. The team keeps productive strangeness and clarifies the kind that interrupts an action the game expects someone to complete.`,`Localisation is often invisible when it works. Players remember the guard, the puzzle or the argument, not the size of a text box. Reviewers may never see the alternatives that were tested and rejected. That invisibility should not hide the creative judgement involved. Fidelity is not measured by counting unchanged objects in a sentence; it is the careful preservation of relationships among language, action, tone and player choice, even when the most faithful solution contains entirely different words.`],questions:[[`detail`,`Why was the original basket proverb unsuitable?`,[`Its source-language recording was longer than the scene animation`,`It revealed a clue that players were meant to discover later`,`Its comic image would not be understood by the target audience`,`It appeared on a menu button with too little space`],2,`The image was familiar and amusing in the source language but meaningless to most target players.`,`Противопоставление familiar и meaningless показывает, что целевая аудитория не поняла бы комический образ исходной пословицы.`],[`inference`,`Why did the team avoid using an existing local proverb?`,[`It mentioned an object absent from every game scene`,`It would make the guard sound calm rather than frightened`,`It could not be recorded by the chosen voice actor`,`It might wrongly connect the fictional character to a real culture`],3,`Replacing it with a local proverb would have suggested the fictional guard came from a real modern country.`,`Слова would have suggested показывают нежелательный вывод о происхождении героя, поэтому реальную местную пословицу отвергли.`],[`purpose-attitude`,`What did Gabriel’s shared note achieve?`,[`It documented the reasoning and intended effect of a creative departure`,`It instructed test players which part of the joke should be funny`,`It prevented translators from changing any later dialogue`,`It listed every object that remained identical to the source text`],0,`explaining what had been altered and which dramatic effect the team intended to keep.`,`Формулировка показывает содержание заметки: она делала прозрачными изменение текста и сохраняемую драматическую функцию.`],[`reference`,`What may be unable to hold a longer phrase in paragraph 4?`,[`The spreadsheets sent to language teams`,`The interface areas built for short commands`,`The essential meanings removed during editing`,`The letters reduced to an unreadable size`],1,`A menu button designed around a short English command may not hold a longer phrase in another language.`,`Предложение называет menu button как ограниченное пространство, поэтому подразумеваемая область для фразы — интерфейсная кнопка.`],[`vocabulary-context`,`What does “surrender” suggest in paragraph 5?`,[`Become easier for actors to pronounce naturally`,`Preserve the timing of the original warning exactly`,`Give way while the other design elements remain unchanged`,`Replace code and animation with written instructions`],2,`Gabriel dislikes the phrase “making the language fit,” because it sounds as if language alone must surrender.`,`Слова language alone противопоставляют одностороннюю уступку совместной правке, показывая значение surrender как вынужденного подчинения.`],[`main-idea`,`How does Gabriel define fidelity in localisation?`,[`As retaining every cultural reference regardless of player confusion`,`As shortening all translations to match the English word count`,`As making creative work completely invisible to the development team`,`As preserving the experience created by several interacting elements`],3,`it is the careful preservation of relationships among language, action, tone and player choice`,`Заключительная цитата прямо раскрывает верность как сохранение связей языка, действия, тона и выбора, а не отдельных слов.`],[`inference`,`Which unfamiliar detail would Gabriel most likely keep?`,[`A festival name whose mystery encourages exploration`,`A command whose wording prevents the required action`,`A joke that target players consistently misunderstand`,`A warning that continues after the animated danger ends`],0,`A mysterious festival name may invite discovery, while an untranslated instruction may merely punish the player.`,`Сопоставление показывает, что продуктивная загадочность названия поддерживает исследование, тогда как непонятная инструкция только мешает действию.`]]}),a({slug:`map-made-of-memories`,title:`A map made of memories`,topic:`community-flood-planning`,genre:`civic-planning-case-study`,cefr:`B2`,paragraphs:[`After two sudden floods in Bellhaven, the council commissioned a digital model of where rainwater would travel. Engineers combined ground height, drain capacity and rainfall records. The model was detailed, yet its first public version missed several lanes where residents remembered water entering homes. Insurance claims confirmed damage but rarely described the water’s route. Rather than dismiss those memories as unscientific, planner Javed Khan organised mapping sessions in the neighbourhoods most affected.`,`At each session, a large paper map covered several tables. Residents marked where water first appeared, how deep it became and which route they used to leave. Different coloured pencils distinguished times during the storm. Facilitators invited tenants as well as property owners, since their routes and responsibilities could differ. Javed asked them to separate what they had personally seen from what a neighbour had reported. This did not make second-hand information worthless; it gave every mark a visible source, allowing engineers to decide what needed checking on site.`,`Some recollections contradicted one another. On Willow Lane, one family said water had come from the river, while another insisted it rose through drains. Neither household could see the entire lane during the worst hour. A field visit found leaves and plastic blocking a small channel behind both homes. Water had backed up into the drainage system, producing signs that supported part of each account. The disagreement identified a connection the original model had represented poorly.`,`Memories also supplied details that sensors could not. A shopkeeper recalled that delivery vans had created waves against temporary door barriers. A teenager described a dark underpass where people had turned back, although the water was shallow. An emergency sign there had become unreadable after its light failed. These observations shifted the discussion from predicting depth alone to understanding how people actually move, judge danger and protect buildings during a storm.`,`The revised plan includes practical changes at several scales. The council clears the hidden channel before the wet season, has raised electrical equipment in the underpass and sends delivery restrictions when a flood warning is active. A backup sign marks the safer walking route. Maintenance teams record each clearance so a neglected task cannot look like a design failure. It also reserves money for larger drain improvements. Javed stresses that resident testimony did not replace engineering calculations; it helped decide where those calculations required closer attention.`,`There are limits to memory. Dramatic incidents are easier to recall than uneventful hours, and estimated depths change as stories are repeated. People who moved away were also less likely to attend the sessions. The project therefore keeps original notes, confidence labels and later measurements together. If a claim cannot be confirmed, it remains visible as an unresolved report rather than quietly becoming either a fact or a mistake. This protects useful uncertainty from false precision.`,`Bellhaven’s map is now both a model and a record of lived experience. Its value lies less in producing one perfect picture than in revealing why different forms of evidence disagree. New storm reports can be compared with earlier predictions rather than beginning another archive from zero. Numbers can show where water should go under stated conditions; residents can expose blocked routes, frightened decisions and temporary obstacles. Planning improves when each source is asked the question it can genuinely answer.`],questions:[[`detail`,`What weakness appeared in the first digital model?`,[`It used rainfall records from a different region`,`It omitted some locations residents said had flooded`,`It depended entirely on unverified neighbour reports`,`It predicted water depths but no escape routes`],1,`its first public version missed several lanes where residents remembered water entering homes.`,`Слова missed several lanes показывают конкретный недостаток первой модели: в ней отсутствовали некоторые реально затронутые места.`],[`inference`,`Why were participants asked to identify the source of each memory?`,[`So families could receive payment for the most accurate marks`,`So second-hand accounts could be removed from the map immediately`,`So reports could be assessed and checked with appropriate care`,`So engineers could avoid making any further site visits`],2,`it gave every mark a visible source, allowing engineers to decide what needed checking on site.`,`Фрагмент показывает, что источник отметки помогал оценить свидетельство и направить последующую проверку инженеров.`],[`purpose-attitude`,`Why is the Willow Lane disagreement described?`,[`To prove that both families had exaggerated the flood damage`,`To show that river water never affected the drainage network`,`To argue that blocked channels are the cause of every flood`,`To show conflicting accounts can reveal a hidden link`],3,`The disagreement identified a connection the original model had represented poorly.`,`Заключительное предложение эпизода прямо показывает авторскую цель: противоречие помогло обнаружить плохо отражённую связь систем.`],[`reference`,`What does “These observations” refer to?`,[`Details about waves and people’s route choices`,`The calculated heights produced by the digital model`,`The leaves and plastic found behind Willow Lane homes`,`The council’s future programme of drainage improvements`],0,`A shopkeeper recalled that delivery vans had created waves against temporary door barriers. A teenager described a dark underpass where people had turned back`,`Два предыдущих примера показывают, что These observations относится к воспоминаниям о волнах от машин и поведении людей.`],[`vocabulary-context`,`What does “scales” mean in paragraph 5?`,[`Devices for weighing plastic removed from channels`,`Levels ranging from small actions to major investments`,`Numeric systems used to estimate water depth`,`Maps printed at several different physical sizes`],1,`The revised plan includes practical changes at several scales.`,`Следующее перечисление мелкой очистки, оборудования, ограничений и крупных улучшений показывает разные уровни масштаба действий.`],[`main-idea`,`How are residents’ memories used in Bellhaven?`,[`As a complete substitute for technical flood calculations`,`As confirmed facts whenever several neighbours agree`,`As sourced evidence that can reveal gaps and guide checks`,`As dramatic stories included mainly to attract public funding`],2,`resident testimony did not replace engineering calculations; it helped decide where those calculations required closer attention.`,`Противопоставление not replace и helped decide показывает дополнительную роль свидетельств: находить пробелы и направлять техническую проверку.`],[`inference`,`What is meant by protecting uncertainty from “false precision”?`,[`Leaving every resident claim outside the official planning record`,`Converting estimated depths into exact figures for the model`,`Treating all unresolved reports as errors until measurement`,`Keeping unclear claims labelled instead of pretending certainty`],3,`it remains visible as an unresolved report rather than quietly becoming either a fact or a mistake.`,`Формулировка unresolved report показывает сохранение неопределённого статуса без ложного превращения сообщения в точный факт или ошибку.`]]}),a({slug:`month-on-an-imaginary-mars`,title:`A month on an imaginary Mars`,topic:`analogue-space-mission`,genre:`technology-experiment-diary`,cefr:`B2`,paragraphs:[`For thirty days, six volunteers lived inside a white dome in a remote desert and pretended that the red ground outside was Mars. Nobody believed the simulation could reproduce another planet. Gravity, danger and distance remained entirely different. The landscape provided isolation and a convincing visual frame, not a duplicate world. Mission leader Dr Saira Nordin described the dome as a tool for asking narrower questions: how do people share limited space, organise delayed communication and make ordinary decisions when leaving the building requires a procedure?`,`The crew could step outside only in mock spacesuits and pairs. Preparing the suits took twenty minutes, so a forgotten tool was not a small inconvenience. During the first week, team members repeatedly returned for batteries, sample bags or labels. They responded by creating a checklist beside the airlock and assigning one person to read it aloud. Each delay was logged so the team could distinguish irritation from a recurring process flaw. Preparation became slower on paper but faster in practice because fewer trips had to be repeated.`,`Communication with “Earth” carried a ten-minute delay in each direction. The control team knew immediately if a message was unclear, but the crew would wait twenty minutes for a question and reply. At first both sides sent short notes to save time. This produced more confusion, not less. They later used headings for decisions, observations and requests, and included the evidence behind a recommendation so recipients could act without another round of clarification.`,`The hardest conflict concerned noise rather than scientific work. Two people held evening video logs while others tried to sleep. Headphones solved only half the problem because speaking voices still crossed the thin walls. Private corners were scarce, so moving the speaker elsewhere was not a realistic answer. The crew moved recordings to one shared hour and created a silent period afterwards. Saira noted that the solution worked because everyone surrendered a little convenience; no person was labelled the difficult one who simply had to adapt.`,`Food offered another lesson. The mission supplied enough calories, but repeated meals affected enthusiasm. Crew members began saving small ingredients such as herbs or dried fruit for a weekly shared dinner. Choosing how to use them became a rare decision unrelated to safety or experiment schedules. These additions had little nutritional importance, yet planning the meal created anticipation and a reason to gather without discussing tasks. Researchers recorded the ritual as a social resource, not as proof that a particular menu would suit real astronauts.`,`Several measurements were deliberately subjective. Each evening, volunteers rated privacy, workload and mood, then added a short explanation. A low score on one day could reflect a headache, an argument or bad news from home. Rather than averaging those causes away, researchers compared ratings with diary entries and schedules. The numbers helped them locate moments worth examining; the words helped them avoid inventing a simple story around a changing line.`,`When the dome opened, journalists asked whether the crew had proved humans could live on Mars. Saira answered no. The project had tested routines under chosen constraints with six particular people. Its value lay in exposing preventable friction: unclear messages, repeated preparation errors and unprotected quiet time. A simulation is useful, she argued, when it makes assumptions visible enough to redesign—not when its dramatic setting tempts observers to claim more than the experiment can support.`],questions:[[`detail`,`What was the stated purpose of the desert dome?`,[`To investigate specific routines under controlled limitations`,`To reproduce every physical condition found on Mars`,`To train volunteers to survive genuine planetary dangers`,`To compare desert gravity with measurements from space`],0,`Mission leader Dr Saira Nordin described the dome as a tool for asking narrower questions`,`Слова narrower questions показывают ограниченную исследовательскую цель купола, а не попытку полностью воспроизвести другую планету.`],[`inference`,`Why did the airlock checklist save time in practice?`,[`It shortened the process of putting on each mock spacesuit`,`It reduced repeated exits caused by forgotten equipment`,`It allowed volunteers to leave the dome without partners`,`It moved sample labelling from outdoors into bedrooms`],1,`Preparation became slower on paper but faster in practice because fewer trips had to be repeated.`,`Причинная формулировка показывает, что проверка занимала время, но предотвращала повторные выходы за забытыми предметами.`],[`purpose-attitude`,`Why did the crew change the structure of delayed messages?`,[`To hide disagreements from the remote control team`,`To make every note shorter than the first-week messages`,`To let recipients decide without another long clarification cycle`,`To separate scientific staff from ordinary mission decisions`],2,`included the evidence behind a recommendation so recipients could act without another round of clarification.`,`Слова so recipients could act показывают цель новой структуры: дать достаточно оснований для решения без дополнительного двадцатиминутного обмена.`],[`reference`,`What does “the solution” in paragraph 4 refer to?`,[`Using headphones for every evening conversation`,`Building thicker walls inside the experimental dome`,`Asking one person to stop making all video logs`,`Scheduling recordings together and protecting later silence`],3,`The crew moved recordings to one shared hour and created a silent period afterwards.`,`Предыдущее предложение называет общее время записи и последующую тишину, на этот договор и указывает the solution.`],[`vocabulary-context`,`What does “ritual” mean in the discussion of food?`,[`A repeated shared activity with social value`,`A medical rule for calculating daily calories`,`A private reward given to the mission leader`,`A test of fruit preserved for space travel`],0,`planning the meal created anticipation and a reason to gather without discussing tasks.`,`Слова reason to gather показывают, что ritual означает повторяющееся совместное действие, важное для общения, а не питания.`],[`main-idea`,`How does the passage evaluate subjective ratings?`,[`They should be averaged without reading personal explanations`,`They are useful pointers when interpreted with qualitative context`,`They provide stronger proof than schedules or diary entries`,`They become reliable only when every participant reports high mood`],1,`The numbers helped them locate moments worth examining; the words helped them avoid inventing a simple story`,`Цитата показывает дополняющие роли чисел и комментариев: оценки находят важный момент, а слова защищают от упрощённого вывода.`],[`inference`,`Which claim would Saira most likely reject?`,[`Simulations can reveal flaws in routines and communication`,`Chosen constraints can make hidden assumptions easier to notice`,`One dramatic trial proves people are ready to settle Mars`,`A small study should describe the limits of its participants`],2,`Saira answered no. The project had tested routines under chosen constraints with six particular people.`,`Прямой отказ и слова six particular people показывают, что Сайра отвергает широкое доказательство готовности человечества к Марсу.`]]}),a({slug:`who-rides-after-midnight`,title:`Who rides after midnight?`,topic:`late-night-public-transport`,genre:`investigative-newspaper-report`,cefr:`B2`,paragraphs:[`When Eastport proposed ending its two night-bus routes, officials described the vehicles as almost empty. The claim came from ticket totals: an average of eleven paid journeys per bus after midnight. No published table separated weekdays, stops or ticket types. Reporter Leila Grant wondered who those eleven passengers were and what would happen without the service. A small number can indicate waste, she wrote, but it can also hide a group for whom one connection carries unusual importance.`,`Leila rode every departure for one week and spoke with passengers who agreed to be interviewed. Hospital cleaners, hotel workers and kitchen staff formed the largest group. Several had finished shifts after the last regular train. Others used the bus only twice a week, which meant a monthly pass looked poor value even though the individual journey was essential. Caring responsibilities made some workers’ schedules change from one week to the next. The riders were dispersed in statistics but remarkably similar in circumstance.`,`The operator’s cost estimate included driver time, fuel and maintenance, but not the consequences of cancellation. Leila therefore compared alternative journeys. A taxi consumed nearly a quarter of some workers’ nightly pay. Walking took up to ninety minutes along roads with unlit sections. Cycling was mentioned, but secure storage and safe winter routes were inconsistent. None of these alternatives was equally realistic for every passenger. Two people said they would refuse late shifts, transferring the transport problem to employers already struggling to fill those hours.`,`Her reporting also challenged the route itself. The bus followed the daytime path through an office district that was deserted at night, then missed a large distribution centre by less than a kilometre. Drivers said they had mentioned this for years, but suggestions were stored as informal comments rather than demand data. Leila obtained shift times from the centre and found that one departure ended nine minutes before hundreds of workers left.`,`After the article appeared, the council paused cancellation and ran a twelve-week trial. One route moved closer to the distribution centre and left fifteen minutes later. Employers displayed the timetable, while the operator allowed contactless single fares at the same discount as app tickets. The trial covered winter weeks as well as the busy holiday season. Passenger numbers doubled, although they remained modest compared with daytime services. The important comparison was with the previous night route, not with a crowded morning bus.`,`The trial did not solve every concern. A later departure was less useful to one hospital team, and residents near the new stop reported engine noise. The council added a request stop and asked drivers not to wait with engines running. A public log recorded complaints alongside boarding numbers rather than treating either as the whole verdict. Leila included those complaints in her follow-up because a service can be socially valuable without making every design choice correct or every cost disappear.`,`Eastport kept one revised route and replaced the other with a smaller on-demand vehicle. Leila’s articles did not argue that all quiet buses must survive unchanged. They showed that ridership is partly produced by route, price and timetable, so existing passenger totals cannot answer every policy question. Before removing a link, decision-makers should understand whose journeys the average contains and whether a better design can reveal demand the old service failed to meet.`],questions:[[`detail`,`What prompted Leila to investigate the night buses?`,[`A hospital requested more departures for its cleaning staff`,`Drivers refused to continue through an unlit office district`,`Taxi companies raised their prices after midnight`,`Low totals were used to justify ending the routes`],3,`The claim came from ticket totals: an average of eleven paid journeys per bus after midnight.`,`Цитата показывает основу предложения об отмене — низкое среднее число оплаченных ночных поездок, которое Лейла решила изучить глубже.`],[`inference`,`Why could monthly-pass data underestimate reliance on the bus?`,[`Some essential users travelled too rarely to buy a pass`,`Most late workers received free tickets from their employers`,`Contactless fares were counted as daytime journeys`,`Passengers shared one pass across several night shifts`],0,`Others used the bus only twice a week, which meant a monthly pass looked poor value even though the individual journey was essential.`,`Фрагмент показывает, что редкая частота делала проездной невыгодным, хотя отдельная поездка оставалась необходимой для работы.`],[`purpose-attitude`,`Why does the passage compare taxi costs and walking times?`,[`To recommend that every passenger receive a taxi allowance`,`To show costs of cancellation missing from the operator’s calculation`,`To prove walking was impossible for all eleven travellers`,`To estimate how much fuel the night buses consumed`],1,`The operator’s cost estimate included driver time, fuel and maintenance, but not the consequences of cancellation.`,`Противопоставление included и not показывает цель сравнения: раскрыть последствия отмены, отсутствовавшие в узкой смете оператора.`],[`reference`,`What does “this” in “drivers said they had mentioned this” refer to?`,[`The shortage of hotel staff willing to work late`,`The informal method used for storing driver comments`,`The route passing near but not serving the distribution centre`,`The price difference between app and contactless tickets`],2,`The bus followed the daytime path through an office district that was deserted at night, then missed a large distribution centre by less than a kilometre.`,`Предыдущее предложение описывает неудачную трассу рядом с центром, поэтому this указывает именно на этот маршрутный недостаток.`],[`vocabulary-context`,`What does “paused” mean in the account of the council decision?`,[`Permanently rejected without further discussion`,`Transferred to the regional transport operator`,`Announced publicly through the newspaper article`,`Temporarily stopped while a trial was conducted`],3,`After the article appeared, the council paused cancellation and ran a twelve-week trial.`,`Сочетание paused cancellation с последующим trial показывает временную остановку решения ради проверки, а не окончательный отказ.`],[`main-idea`,`What broader point do Leila’s articles make?`,[`Current ridership may reflect a service’s design as well as need`,`Every public route should be judged against morning passenger totals`,`Small vehicles always cost less than scheduled night buses`,`Worker interviews are more reliable than any ticket statistics`],0,`They showed that ridership is partly produced by route, price and timetable`,`Заключительная формулировка прямо показывает, что пассажиропоток зависит не только от потребности, но и от устройства самой услуги.`],[`inference`,`Why were complaints included in the follow-up article?`,[`To reverse the earlier argument and demand immediate cancellation`,`To acknowledge that public value does not remove design trade-offs`,`To demonstrate that the new route had fewer passengers than before`,`To blame hospital workers for resisting the later departure`],1,`a service can be socially valuable without making every design choice correct or every cost disappear.`,`Формулировка without показывает позицию автора: польза маршрута совместима с реальными недостатками, которые следует честно учитывать.`]]}),a({slug:`lunchroom-as-a-laboratory`,title:`The lunchroom as a laboratory`,topic:`school-food-choice-research`,genre:`education-experiment-explainer`,cefr:`B2`,paragraphs:[`Riverside School wanted pupils to choose more vegetables at lunch. Its first idea was a poster campaign explaining vitamins. Biology teacher Priya Shah suggested testing the lunchroom itself before producing advice. Pupils already knew vegetables were generally healthy; knowledge was not necessarily the barrier between the serving counter and their trays. The project team included kitchen staff because they understood queues and preparation limits better than outside researchers. The school agreed to run small trials, changing one practical feature at a time and measuring selection as well as waste.`,`During the first week, vegetables stood at the end of the counter after the main dish. Many pupils had already filled their plates or spent most of their lunch money. The next week, staff moved two vegetable choices to the beginning and kept recipes identical. Selection rose, but so did uneaten portions. Priya cautioned that food placed on a tray was not evidence that anybody had enjoyed or even tasted it.`,`Student interviews explained part of the waste. Large serving spoons produced adult-sized portions, and asking staff for less felt awkward when a queue waited behind. Several pupils said they disliked rejecting food directly in front of the person who had served it. The kitchen introduced small tasting portions with an invitation to return for more. Waste fell sharply, while the total amount eaten rose slightly. The change gave uncertain pupils a reversible choice instead of asking them to commit to a full serving in public.`,`A second trial renamed dishes. “Steamed carrots” became “carrots with orange and ginger,” a description that accurately named the flavour. Priya rejected invented labels such as “superhero carrots,” which younger pupils found childish and older ones distrusted. Descriptive names increased tasting only when the promised flavour was noticeable. When the kitchen once forgot the ginger, complaints increased because the label had created an expectation the food did not meet.`,`The project then examined social influence. On one day, older student volunteers ate lunch near younger classes and talked naturally about what they liked. Vegetable selection rose, but Priya refused to call the effect pure peer leadership. The volunteers also shortened queues by helping pupils find cutlery and seats. The apparent social effect might therefore have included a practical reduction in pressure. A later trial separated these roles, allowing the team to distinguish modelling a choice from simply making lunchtime less stressful.`,`Not all changes were kept. Colourful arrows on the floor attracted attention for three days and then became part of the background. A prize for empty plates was removed immediately because it encouraged pupils to take tiny meals or eat after they were full. Teachers also worried that the reward ignored allergies and sensory difficulties. The goal was not obedience or a clean-bin competition. It was to make a nutritious option easy to try while preserving appetite, preference and the right to stop.`,`After one term, vegetable consumption had risen modestly and waste had declined. Results varied by dish, so the school kept publishing separate figures instead of one promotional percentage. The most useful result was not a universal trick but a method: observe the real decision, test a limited change and measure consequences beyond the desired number. Riverside still teaches nutrition in class. It now recognises that information works inside an environment, and that improving the environment requires listening to the people making choices within it.`],questions:[[`detail`,`What did Priya propose before launching the poster campaign?`,[`Replacing every main dish with a vegetable meal`,`Surveying parents about their vitamin knowledge`,`Testing practical features of the lunch setting`,`Offering prizes for pupils who cleared their plates`],2,`Biology teacher Priya Shah suggested testing the lunchroom itself before producing advice.`,`Цитата прямо показывает предложение Прии: сначала проверить среду столовой, а не сразу выпускать информационные советы.`],[`inference`,`Why did moving vegetables first provide incomplete evidence of success?`,[`Staff stopped recording the contents of returned trays`,`Recipes changed at the same time as counter order`,`Lunch prices prevented pupils buying any main dish`,`Pupils selected more but also left more uneaten`],3,`Selection rose, but so did uneaten portions.`,`Короткое противопоставление показывает, что рост выбора сопровождался ростом отходов и не доказывал реальное потребление.`],[`purpose-attitude`,`What was the advantage of small tasting portions?`,[`They lowered the social and practical risk of trying something`,`They made vegetables cheaper than every other lunch item`,`They guaranteed that pupils would return for a second helping`,`They allowed kitchen staff to remove serving spoons completely`],0,`The change gave uncertain pupils a reversible choice instead of asking them to commit to a full serving in public.`,`Слова reversible choice показывают преимущество: ученик мог попробовать небольшую порцию без публичного обязательства взять и съесть большую.`],[`reference`,`What does “the promised flavour” refer to?`,[`The nutritional benefit described in classroom posters`,`The orange-and-ginger taste named on the label`,`The familiar recipe used during the first counter trial`,`The sweetness suggested by the superhero name`],1,`“Steamed carrots” became “carrots with orange and ginger,” a description that accurately named the flavour.`,`Предыдущее название конкретно обещает вкус апельсина и имбиря, поэтому формулировка promised flavour указывает на него.`],[`vocabulary-context`,`What does “modelling” mean in paragraph 5?`,[`Calculating lunch demand with a computer simulation`,`Designing a more attractive school dining room`,`Demonstrating a behaviour that others may imitate`,`Serving accurately measured vegetable portions`],2,`allowing the team to distinguish modelling a choice from simply making lunchtime less stressful.`,`Сопоставление с поведением старших показывает, что modelling означает наглядный пример выбора, который младшие могут повторить.`],[`main-idea`,`Which principle best describes Riverside’s final method?`,[`A strong slogan can produce lasting behaviour without environmental change`,`Only changes that increase selection should be measured`,`Pupil preference matters less than reducing visible waste`,`Small trials should examine intended and unintended outcomes`],3,`observe the real decision, test a limited change and measure consequences beyond the desired number.`,`Формулировка directly раскрывает метод: наблюдать реальный выбор, ограниченно менять условие и учитывать последствия шире желаемого показателя.`],[`inference`,`Why was the empty-plate prize stopped?`,[`It rewarded behaviour that could conflict with healthy self-regulation`,`It cost more than the school nutrition campaign could afford`,`It made older volunteers leave the lunchroom too early`,`It caused the vegetable queue to move more slowly`],0,`it encouraged pupils to take tiny meals or eat after they were full.`,`Слова цитаты показывают два нежелательных поведения, противоречащих нормальному аппетиту и цели здорового самостоятельного выбора.`]]}),a({slug:`photographs-without-names`,title:`Photographs without names`,topic:`community-photo-archive`,genre:`archive-curator-profile`,cefr:`B2`,paragraphs:[`When archivist Tomas Reed opened a box donated by a closed newspaper, he found three thousand negatives and almost no captions. The images showed factory gates, school plays, demonstrations and ordinary streets from the 1970s. Without names or dates, they were visually rich but difficult to search. The newspaper’s filing order had been lost during several office moves. Tomas could have stored them as an anonymous collection; instead, he designed a public identification project that treated local memory as evidence requiring care.`,`The archive first digitised five hundred images at low resolution. Volunteers numbered every frame and recorded visible clues before asking for help: shop signs, bus routes, weather, uniforms and construction sites. This step prevented the project from depending entirely on recognition of faces. It also gave residents something specific to discuss. A person unsure about a teacher’s name might still identify the school from a distinctive doorway.`,`At monthly sessions, photographs appeared on large screens. Participants wrote suggestions on separate cards rather than changing the archive record directly. Tomas noticed that confident voices could influence a room, especially when a popular local story was involved. Quiet participants could submit cards after the discussion rather than defend a memory publicly. He therefore asked people to mark whether they knew a fact personally, inferred it from the picture or remembered hearing it from someone else. Agreement increased confidence but did not automatically create certainty.`,`One photograph seemed to show the famous flood of 1976 because people recognised water outside a bakery. A bus enthusiast pointed out that the vehicle in the background entered service two years later. Further research revealed a burst water main in 1979. The correction disappointed residents attached to the flood story, yet it made the image more useful: researchers could now connect it to records about repairs and temporary street closures.`,`Naming people raised privacy questions. Some photographs had been taken at public events, while others showed patients leaving a clinic or children in distress. A name harmless in a family album might expose sensitive information when linked to a public image. The archive did not publish every identification it received. Sensitive names remain in a restricted note available to authorised researchers under clear conditions. Tomas argues that preserving a fact and making it instantly searchable on the open internet are separate decisions, not one automatic act.`,`The project also returns information to contributors. When a retired printer identified colleagues at a newspaper press, staff sent him a copy of the updated record. He replied with an audio description of the noise, heat and teamwork in the room. That recording became linked to the photograph, adding experience the image could not contain. The archive retained his wording while clearly labelling the recording as personal testimony. Contributors saw that their knowledge changed a shared resource rather than disappearing into an institution.`,`After four years, fewer than half the digitised images have complete captions. Tomas considers this partial result honest rather than disappointing. Blank fields remain visible, competing suggestions are retained, and every change has a source. Future researchers can therefore revisit a conclusion instead of inheriting unexplained certainty. This audit trail matters as new records become available. The archive is becoming easier to search, but it is also documenting how knowledge is built: through observation, disagreement, correction and sometimes the disciplined decision to leave a person unnamed.`],questions:[[`detail`,`What did volunteers record before seeking public identifications?`,[`Only the faces of people who appeared repeatedly`,`Clues visible within each numbered photograph`,`Stories previously printed by the closed newspaper`,`Names supplied by former reporters and editors`],1,`Volunteers numbered every frame and recorded visible clues before asking for help`,`Цитата показывает предварительный этап: кадры нумеровали и фиксировали видимые признаки до обращения к памяти жителей.`],[`inference`,`Why were suggestions written on separate cards?`,[`To let contributors take the original negatives home`,`To count which local story attracted the largest audience`,`To keep unverified memories outside the archive record`,`To prevent residents from discussing photographs together`],2,`Participants wrote suggestions on separate cards rather than changing the archive record directly.`,`Противопоставление rather than показывает, что карточки отделяли предложения участников от уже подтверждённой архивной записи.`],[`purpose-attitude`,`What does the flood photograph episode demonstrate?`,[`Low-resolution images should never be used for research`,`Public identification works only when transport experts attend`,`Residents generally prefer repair records to dramatic stories`,`A small visual detail can overturn a confident shared interpretation`],3,`the vehicle in the background entered service two years later.`,`Деталь о дате автобуса противоречит уверенной версии о наводнении и показывает, как проверяемый признак исправляет коллективную память.`],[`reference`,`What does “it” refer to in “it made the image more useful”?`,[`The corrected identification of a different water incident`,`The famous flood story repeated by local residents`,`The digitisation of every negative at high resolution`,`The temporary closure of streets around the bakery`],0,`Further research revealed a burst water main in 1979. The correction disappointed residents attached to the flood story, yet it made the image more useful`,`Предыдущие слова называют исправление события и даты, поэтому it указывает на эту уточнённую идентификацию снимка.`],[`vocabulary-context`,`What does “restricted” mean when describing a note?`,[`Written in language that contributors cannot understand`,`Available only to approved users under stated rules`,`Reduced to a shorter caption for online publication`,`Removed permanently from every archive database`],1,`Sensitive names remain in a restricted note available to authorised researchers under clear conditions.`,`Слова available to authorised researchers показывают, что restricted означает ограниченный доступ для допущенных пользователей по правилам.`],[`main-idea`,`Which balance does Tomas’s project seek?`,[`Completing every caption quickly while avoiding public meetings`,`Giving popular memories priority over technical evidence`,`Using local knowledge while preserving uncertainty and privacy`,`Publishing all known names but hiding disputed dates`],2,`Blank fields remain visible, competing suggestions are retained, and every change has a source.`,`Перечисление показывает честное сохранение пробелов, разногласий и источников при постепенном использовании знаний сообщества.`],[`inference`,`Why did sending updated records back to contributors matter?`,[`It allowed them to sell corrected photographs commercially`,`It replaced the need for storing their original suggestion cards`,`It proved that the archive had completed every caption`,`It showed their knowledge had a visible effect and invited more context`],3,`Contributors saw that their knowledge changed a shared resource rather than disappearing into an institution.`,`Формулировка changed a shared resource показывает видимый результат участия и объясняет, почему люди могли добавлять новые содержательные сведения.`]]}),a({slug:`fire-used-with-care`,title:`Fire used with care`,topic:`forest-prescribed-burning`,genre:`environmental-management-essay`,cefr:`B2`,paragraphs:[`To many visitors, deliberately setting fire to a nature reserve sounds like destruction, not conservation. At Pine Ridge, however, managers use small planned burns in selected grassland and open woodland. The practice remains controversial because recent wildfires have made smoke and flame symbols of danger. Ecologist Anika Roy begins every public meeting by acknowledging that fear rather than treating concerned residents as people who simply misunderstand science.`,`Pine Ridge evolved with frequent low fires caused by lightning and, historically, managed by Indigenous communities. These burns removed dry grass and allowed sunlight to reach plants adapted to open ground. A century of suppressing nearly every flame changed the structure: shrubs thickened, dead material accumulated and young trees filled spaces where rare flowers once grew. Avoiding fire had not preserved a fixed natural condition; it had produced a different, increasingly dense landscape.`,`A prescribed burn is not a wildfire released under a nicer name. Teams map boundaries, create control lines and wait for a narrow range of wind, humidity and soil moisture. Fire crews, medical support and weather observers are present. If conditions move outside the agreed range, the burn is postponed even after weeks of preparation. Anika calls cancellation evidence that the safety system is working, not an embarrassing failure of courage.`,`Before the first burn near homes, managers established monitoring plots inside and outside the planned area. They counted key plants, measured dead fuel and photographed vegetation from fixed points. This baseline mattered because any green growth after fire might look like recovery to a casual observer. Comparison plots help separate the effect of burning from seasonal rain, grazing animals or changes already happening elsewhere in the reserve.`,`Smoke presents the hardest immediate trade-off. Managers notify residents, avoid days when air pollution is already high and keep burns small. Even so, smoke cannot be made harmless for everyone, particularly people with breathing conditions. The reserve therefore publishes expected direction and duration, provides a phone line and coordinates with health services. These measures reduce exposure; they do not turn a real cost into a public-relations detail.`,`Results after three years are mixed but informative. Several open-ground flowers have expanded, and the amount of dry surface fuel has fallen. One bird species did not return as quickly as predicted because suitable nesting shrubs recovered slowly. Rather than label the programme successful or unsuccessful as a whole, managers changed the interval between burns in that area and left connected unburned patches as temporary cover.`,`The project has also changed who participates in decisions. Local fire crews contribute knowledge about access and wind, while Indigenous land practitioners advise on seasonal signs and the purpose of burning particular places. Their knowledge is not displayed as a ceremonial addition to an unchanged technical plan. Burn proposals are revised in response, and the reserve records who made each recommendation and how it affected the final operation.`,`Anika does not argue that every forest needs more fire. Wet woodland, exhausted soil and extreme weather can make burning damaging or impossible. Her argument is against a simpler assumption: that doing nothing is neutral. Land already carries the effects of earlier suppression, drainage and settlement. Responsible management means comparing interventions and their costs openly, then monitoring whether a carefully chosen action actually produces the ecological relationship it was meant to support.`],questions:[[`detail`,`What historical change occurred at Pine Ridge?`,[`Long fire suppression helped dense vegetation accumulate`,`Frequent wildfires removed every young tree from wet woodland`,`Indigenous burning caused rare flowers to disappear permanently`,`Lightning became less common after the reserve was established`],0,`A century of suppressing nearly every flame changed the structure: shrubs thickened, dead material accumulated and young trees filled spaces`,`Перечисление в цитате показывает последствия длительного подавления огня: накопление сухого материала и уплотнение растительности.`],[`inference`,`Why is postponing a planned burn not treated as failure?`,[`The reserve receives funding for every cancelled operation`,`Safety rules should override the original schedule`,`Monitoring plots need another season before any fire`,`Residents prefer cancellations to information about smoke`],1,`If conditions move outside the agreed range, the burn is postponed even after weeks of preparation.`,`Условная формулировка показывает приоритет заранее установленных безопасных условий над затратами времени и выбранной датой.`],[`purpose-attitude`,`Why were comparison plots created before burning?`,[`To offer medical teams a safe place during smoke`,`To decide which residents should receive notifications`,`To separate fire effects from other environmental changes`,`To demonstrate that every flower would recover immediately`],2,`Comparison plots help separate the effect of burning from seasonal rain, grazing animals or changes already happening elsewhere`,`Слова help separate показывают исследовательскую цель контрольных участков: отличить влияние огня от дождя, животных и общих изменений.`],[`reference`,`What does “These measures” refer to in paragraph 5?`,[`Counting plants and photographing vegetation from fixed points`,`Changing burn intervals and leaving temporary bird cover`,`Creating control lines around selected woodland areas`,`Warnings, careful timing, public information and health coordination`],3,`The reserve therefore publishes expected direction and duration, provides a phone line and coordinates with health services.`,`Предыдущее перечисление называет меры информирования и координации, поэтому These measures указывает именно на них.`],[`vocabulary-context`,`What does “trade-off” mean in the smoke discussion?`,[`A difficult balance in which a benefit carries a cost`,`A financial exchange between crews and nearby residents`,`A boundary where two fire teams change responsibility`,`A scientific error caused by missing comparison plots`],0,`Smoke presents the hardest immediate trade-off.`,`Последующие слова о пользе управления и реальном вреде дыма показывают, что trade-off означает баланс результата с неизбежной ценой.`],[`main-idea`,`How does Pine Ridge evaluate its burning programme?`,[`It seeks one final label of complete success or failure`,`It monitors separate outcomes and adjusts management accordingly`,`It measures only the reduction of dry surface fuel`,`It follows the same interval in every habitat type`],1,`Rather than label the programme successful or unsuccessful as a whole, managers changed the interval between burns`,`Формулировка rather than показывает отказ от общего ярлыка ради анализа отдельных результатов и изменения практики.`],[`inference`,`What larger assumption does Anika challenge?`,[`Local knowledge should remain outside ecological planning`,`Every landscape can safely be burned in dry weather`,`Managed land is not consequence-free when left untouched`,`Public fear disappears once scientific facts are presented`],2,`Her argument is against a simpler assumption: that doing nothing is neutral.`,`Заключительная цитата прямо показывает оспариваемое предположение: бездействие ошибочно принимают за нейтральное состояние без последствий.`]]}),a({slug:`stage-everyone-can-read`,title:`A stage everyone can read`,topic:`accessible-theatre-design`,genre:`production-designer-interview`,cefr:`B2`,paragraphs:[`Production designer Lorna Webb begins our interview by moving two chairs. “This is design too,” she says, widening the route between them. Her latest youth-theatre production includes captions, audio description and a relaxed performance, but she dislikes calling accessibility a package added after the artistic work. If access arrives only during the final week, it must squeeze around choices that nobody thought to question earlier.`,`For the new play, caption designer Malik attended the first rehearsal. The story moves between a kitchen and an imaginary sea, and dialogue sometimes overlaps. A single caption screen above the stage forced viewers to look away from small physical jokes. Malik proposed projecting short lines onto parts of the set near the speaker. Actors could see the text during rehearsal and adjust positions when a shadow made a word difficult to read.`,`Lorna admits that the first version became too active. Words rolled like waves in almost every sea scene. Some Deaf viewers enjoyed the movement, while others said it competed with faces and made rapid dialogue tiring. The team kept animated captions only at moments when motion carried meaning, such as a repeated word drifting away during a farewell. Ordinary exchanges returned to stable, high-contrast text.`,`Audio description created a different question: what deserves to be said during limited pauses? Describer Jo did not list every colour and object. She followed changes needed to understand action or atmosphere, then shared drafts with blind consultants. One noted that a long description of the painted moon covered the sound of a character secretly opening a letter. Jo shortened the visual detail so the important paper sound remained audible.`,`The relaxed performance changes the environment without presenting one audience as a problem. House lights remain low rather than dark, people may leave and return, and a quiet room is available. The actors follow the same story and do not turn unexpected audience sounds into jokes. Lorna explains that predictability matters: visitors receive a visual guide beforehand, including photographs of loud effects and the route to exits.`,`Some changes benefit people who do not identify as disabled. Captions support language learners and anyone seated far from a quiet speaker. Clear routes help staff carrying equipment as well as wheelchair users. Lorna is careful with this argument, however. Wider usefulness may persuade a budget committee, but disabled people should not have to prove that an access feature serves everyone before their own participation is considered worthwhile.`,`Cost remains real. The theatre cannot afford every possible format on every night, so it publishes exactly what each performance provides and invites requests early. Recorded description is not presented as identical to a live version. Equipment is reused across productions, while specialist artists are paid rather than asked to volunteer. Lorna says transparency is better than a vague promise that a show is “accessible,” a word that means little unless a visitor can discover accessible to whom, in what way and when.`,`As we finish, Lorna rejects the idea that all these decisions produce one perfect design. Preferences conflict: motion helps one viewer and distracts another; bright light supports navigation but changes atmosphere. The aim is not to erase difference. It is to create choices, test them with the people affected and make remaining limits visible, so attendance depends less on guessing whether the theatre has remembered you.`],questions:[[`detail`,`Why did Malik attend rehearsals from the beginning?`,[`To teach actors the entire script through captions`,`To replace the physical jokes with written explanations`,`To decide which audience members needed a caption screen`,`To integrate text with stage movement and positions`],3,`Actors could see the text during rehearsal and adjust positions when a shadow made a word difficult to read.`,`Цитата показывает практическую интеграцию титров с расположением актёров и светом уже во время репетиций.`],[`inference`,`What problem did the first animated-caption version create?`,[`Frequent movement could distract from acting and exhaust readers`,`Stable captions prevented viewers noticing the imaginary sea`,`Actors could not remember which speaker owned each line`,`The projection equipment produced shadows in every kitchen scene`],0,`others said it competed with faces and made rapid dialogue tiring.`,`Слова competed with faces и tiring показывают две проблемы избыточного движения: отвлечение от актёров и нагрузку чтения.`],[`purpose-attitude`,`Why was the moon description shortened?`,[`The painted object was removed from the final set`,`A narrative sound carried more important story information`,`Blind consultants preferred descriptions without any colour`,`The farewell caption needed extra time to drift away`],1,`a long description of the painted moon covered the sound of a character secretly opening a letter.`,`Фрагмент показывает конфликт звуков: длинное описание закрывало важный для сюжета звук тайно открываемого письма.`],[`reference`,`What does “this argument” in paragraph 6 refer to?`,[`Specialist theatre artists should always work as volunteers`,`Relaxed performances require actors to change the story`,`Accessible features can also help a broader audience`,`Every caption should move with the emotional atmosphere`],2,`Some changes benefit people who do not identify as disabled.`,`Предложение прямо формулирует мысль перед this argument: отдельные доступные решения оказываются полезны и более широкой аудитории.`],[`vocabulary-context`,`What does “formats” mean in paragraph 7?`,[`Printed budgets used by the theatre committee`,`Different actors’ interpretations of the same role`,`Standard sizes available for projection equipment`,`Different forms of accessible performance support`],3,`The theatre cannot afford every possible format on every night`,`Контекст последующих точных описаний доступности показывает, что formats означает разные формы поддержки, например титры или аудиоописание.`],[`main-idea`,`What is Lorna’s central view of accessibility?`,[`It is an ongoing design process involving choices and affected users`,`It is achieved once a theatre offers one relaxed performance`,`It should be funded only when every visitor gains equally`,`It requires removing all artistic movement and darkness`],0,`It is to create choices, test them with the people affected and make remaining limits visible`,`Заключительная формулировка раскрывает центральный подход Лорны: создавать варианты, проверять их с пользователями и честно показывать ограничения.`],[`inference`,`Why does Lorna prefer precise information to the word “accessible”?`,[`The word is understood only by theatre professionals`,`Visitors need concrete details to judge whether support fits them`,`Budget committees refuse applications containing that word`,`Precise information removes every remaining access conflict`],1,`a word that means little unless a visitor can discover accessible to whom, in what way and when.`,`Слова to whom, in what way and when показывают необходимость конкретных сведений, чтобы каждый посетитель мог оценить соответствие поддержки своим потребностям.`]]}),a({slug:`feed-that-learned-too-well`,title:`The feed that learned too well`,topic:`news-recommendation-literacy`,genre:`media-algorithm-analysis`,cefr:`B2`,paragraphs:[`For a media-literacy project, nineteen-year-old Hana agreed to record every article recommended to her for two weeks. She expected a random mixture shaped by national news. Instead, the feed quickly became dominated by three topics she had clicked during exam season: university rankings, productivity routines and stories about young entrepreneurs. None was irrelevant, yet their repetition made a temporary concern look like her permanent identity.`,`Recommendation systems learn from actions that are easy to measure. A click, pause or share becomes a signal, but its meaning is uncertain. Hana sometimes opened an alarming headline because she doubted it, and she left a difficult article on screen while making tea. The system could observe time and movement, not her scepticism or absence. Behaviour was real evidence, but it was not a transparent window into intention.`,`Hana then compared her feed with that of a classmate who followed the same news organisations. Their front pages overlapped less than expected. Her classmate saw more sport and local housing stories; Hana received more career advice. The exercise did not reveal one hidden “true” edition. It demonstrated that each user was seeing a selection, while the familiar design made that selection feel like the natural order of importance.`,`For the second week, Hana changed only one habit: she opened the full topic list each morning and deliberately chose one article outside her usual cluster. Some selections bored her; others led to interests the feed could not have predicted from exam-season clicks. Within days, the automated recommendations broadened slightly. This did not prove the user controlled the system, but it showed that small actions could alter the evidence it collected.`,`The platform also offered an option to hide a story. Hana had assumed this meant “I disagree,” so she rarely used it. The help page explained that hiding usually meant “show me fewer items like this,” a much broader instruction. She began using the control for repetitive topics rather than opposing opinions. The wording mattered because an unclear button can discourage useful feedback or turn a content preference into an apparent political judgement.`,`A completely unfiltered feed would not solve the problem. Thousands of articles appear each day, and selection is unavoidable. Editors, search terms, subscription choices and algorithms all create boundaries. The useful question is not whether a feed has been selected, but which goals guide the selection, which signals influence it and what routes let a reader step outside the resulting pattern without needing to abandon the service.`,`Hana’s final presentation included screenshots, but she refused to claim that everyone’s feed would behave like hers. The experiment involved one account over a short period, and the platform might change its system without notice. She presented it as a method classmates could repeat: collect rather than remember, compare rather than assume, change one behaviour and observe what follows. The modest design made the conclusions narrower but easier to defend.`,`Her main conclusion concerned attention. A personalised feed can be convenient while gradually reducing opportunities for surprise. Responsibility is shared: platforms should explain and improve controls, and readers can periodically examine the menu being placed before them. Neither side has complete power. Awareness begins when the smooth sequence of headlines is recognised as a constructed response to incomplete signals, not a neutral mirror of the reader or the world.`],questions:[[`detail`,`Which topics dominated Hana’s first-week feed?`,[`Local housing, team sports and national elections`,`Climate research, arts reviews and travel advice`,`University choices, efficiency habits and young business success`,`International conflict, health policy and food prices`],2,`university rankings, productivity routines and stories about young entrepreneurs.`,`Перечисление в цитате точно называет три преобладающие темы: рейтинги вузов, продуктивность и молодых предпринимателей.`],[`inference`,`Why can time spent on an article be a misleading signal?`,[`The platform records only articles that a reader shares`,`Readers cannot open alarming headlines without agreeing`,`Difficult articles are automatically removed from history`,`A long pause may reflect absence rather than interest`],3,`she left a difficult article on screen while making tea.`,`Конкретный пример показывает, что долгое время на странице могло означать физическое отсутствие, а не повышенный интерес.`],[`purpose-attitude`,`What did comparing two classmates’ feeds demonstrate?`,[`Personal selection can appear like a universal news hierarchy`,`One classmate had secretly followed different news organisations`,`Local housing stories were objectively more important than careers`,`The platform delivered a random front page to every account`],0,`each user was seeing a selection, while the familiar design made that selection feel like the natural order of importance.`,`Противопоставление selection и natural order показывает, как персональная подборка может ошибочно восприниматься как общая иерархия новостей.`],[`reference`,`What does “the evidence it collected” refer to?`,[`Screenshots prepared for Hana’s final presentation`,`Signals from Hana’s observable reading actions`,`Editorial rankings shared by both news organisations`,`The complete topic list opened before each morning`],1,`small actions could alter the evidence it collected.`,`Контекст намеренного открытия новых статей показывает, что evidence означает поведенческие сигналы, которые система собирает из действий пользователя.`],[`vocabulary-context`,`What does “cluster” mean in paragraph 4?`,[`A technical failure affecting several recommendations`,`A class of students sharing one news account`,`A group of closely related familiar topics`,`A list of stories hidden through platform controls`],2,`she opened the full topic list each morning and deliberately chose one article outside her usual cluster.`,`Слова full topic list и outside показывают, что cluster — привычная группа близких тем внутри более широкого выбора.`],[`main-idea`,`What position does the passage take on selected feeds?`,[`All selection should be removed so articles appear neutrally`,`Only professional editors should decide what readers see`,`Users fully control recommendations through every click`,`Selection is inevitable; its mechanisms need examination`],3,`The useful question is not whether a feed has been selected, but which goals guide the selection`,`Формулировка not whether, but which показывает позицию: отбор неизбежен, поэтому нужно исследовать его цели, сигналы и выходы.`],[`inference`,`Why does the writer call Hana’s experimental design “modest”?`,[`Its limited scope supports cautious conclusions`,`It avoided collecting any screenshots or article records`,`It compared every possible platform recommendation system`,`Its results proved a permanent rule about all users`],0,`The experiment involved one account over a short period`,`Слова one account и short period показывают ограниченный масштаб, который требует узких, но лучше обоснованных выводов.`]]}),a({slug:`crop-below-the-tide`,title:`A crop below the tide`,topic:`coastal-seaweed-farming`,genre:`sustainable-business-report`,cefr:`B2`,paragraphs:[`From the harbour, the seaweed farm looks like several lines of small dark floats. Beneath them, ropes carry long brown ribbons that move with the tide. Founder Mae Okafor chose seaweed because it needs no fresh water, artificial fertiliser or farmland. Those advantages attracted headlines calling it a miracle crop. Mae uses the phrase carefully: low input does not mean no impact, and a promising plant cannot solve every coastal problem alone.`,`The farm began with a one-hectare trial in a sheltered bay. Marine biologists mapped eelgrass, currents and bird feeding areas before any rope was placed. Fishers helped identify routes used by small boats and seasons when gear might interfere with nets. The final layout was less efficient on paper because it left wider passages. In practice, those gaps reduced conflict and made inspection easier during rough weather.`,`Seaweed grows fastest in winter and early spring, when the water contains more nutrients. Workers attach tiny seedlings to ropes in autumn and harvest before summer storms become common. Timing is not fixed by a calendar alone. The team samples growth and watches forecasts, sometimes collecting one section early while leaving another. A single dramatic harvest photograph hides weeks of staggered decisions made around changing water.`,`Finding a market proved harder than growing the first crop. Restaurants bought small quantities, but their demand changed weekly. A cosmetics company wanted consistent dried powder, which required equipment the farm did not own. Transporting wet seaweed far inland would remove part of its low-input advantage. Mae formed a cooperative with two other growers to share a dryer and storage room. Shared equipment lowered individual risk, although agreeing quality standards and booking harvest days created new administrative work.`,`The farm measures environmental effects instead of assuming them. Sensors record oxygen and light, while divers photograph the seabed beneath ropes and at comparison sites. Early results show small fish sheltering among the crop, but Mae avoids calling the farm a new reef. The species are seasonal, and dense shade could harm plants below if ropes were packed too closely. Positive observations do not cancel the need to test possible damage.`,`Storm loss remains a practical and ecological concern. A broken line can release plastic fittings and waste an entire section. After one winter failure, the cooperative redesigned connectors and began marking every component. Beach volunteers receive a number to report recovered pieces. Mae publishes losses alongside harvest weight because material that disappears from a balance sheet has not disappeared from the sea.`,`Local jobs are another claimed benefit, but the pattern is uneven. Harvest weeks need many hands, whereas monitoring and sales require smaller teams throughout the year. The cooperative now coordinates with a shellfish business whose busy season is different. Some workers can combine both, creating steadier income. This arrangement is more complicated than promising that each hectare automatically produces a fixed number of permanent jobs.`,`Mae sees seaweed as one useful part of a diverse coast. Expansion should follow evidence about habitats, navigation and real markets, not excitement alone. The farm’s modest scale has allowed mistakes to be corrected before ropes fill the bay. A sustainable crop is defined not only by what it avoids using, she says, but by whether its materials, labour, buyers and surrounding ecosystem can remain in workable relationship over time.`],questions:[[`detail`,`Why does Mae avoid calling seaweed simply a miracle crop?`,[`It grows only when artificial fertiliser is added`,`Its benefits do not remove possible impacts or limits`,`Restaurants refuse to buy plants described in that way`,`The farm must use valuable agricultural land for drying`],1,`Mae uses the phrase carefully: low input does not mean no impact`,`Противопоставление low input и no impact показывает осторожность Мэй: малые ресурсы не означают полного отсутствия последствий.`],[`inference`,`Why was the final rope layout less efficient on paper?`,[`It placed every rope in the roughest part of the bay`,`It required workers to harvest all sections together`,`It included wider gaps for other users and easier access`,`It depended on a dryer located outside the harbour`],2,`The final layout was less efficient on paper because it left wider passages.`,`Причинная формулировка прямо показывает, что теоретическая эффективность снизилась из-за широких проходов для навигации и осмотра.`],[`purpose-attitude`,`Why does the writer mention staggered harvesting?`,[`To suggest workers avoid the farm throughout winter`,`To prove a calendar is useless for planning any coastal work`,`To explain why restaurants receive identical weekly quantities`,`To show farm decisions respond to local growth and weather`],3,`sometimes collecting one section early while leaving another.`,`Контраст collecting one section и leaving another показывает гибкое решение по участкам, основанное на состоянии роста и прогнозах.`],[`reference`,`What does “their demand” refer to in paragraph 4?`,[`The restaurants’ changing purchases of seaweed`,`The growers’ need for shared drying equipment`,`The cosmetics company’s required powder quality`,`The workers’ preferred dates for harvesting`],0,`Restaurants bought small quantities, but their demand changed weekly.`,`Предложение называет restaurants как покупателей, поэтому their demand означает меняющийся в течение недели объём заказов ресторанов.`],[`vocabulary-context`,`What does “comparison sites” mean in paragraph 5?`,[`Markets where several growers compare selling prices`,`Unaffected locations used to judge changes near the farm`,`Harbours used for testing different rope connectors`,`Storage rooms shared by members of the cooperative`],1,`divers photograph the seabed beneath ropes and at comparison sites.`,`Сопоставление beneath ropes и comparison sites показывает контрольные места вне непосредственного влияния фермы для оценки различий.`],[`main-idea`,`Which approach to sustainability does Mae support?`,[`Expanding quickly before competitors occupy suitable bays`,`Counting resource savings while ignoring market demand`,`Testing linked ecological, labour and market factors`,`Replacing every coastal industry with a single low-input crop`],2,`whether its materials, labour, buyers and surrounding ecosystem can remain in workable relationship over time.`,`Перечисление материалов, труда, покупателей и экосистемы показывает широкую проверку устойчивости, а не один показатель низких затрат.`],[`inference`,`Why are component losses published beside harvest weight?`,[`To prove that every broken fitting is recovered`,`To calculate payments owed to beach volunteers`,`To hide the financial effect of winter storm damage`,`To include environmental costs alongside productive output`],3,`material that disappears from a balance sheet has not disappeared from the sea.`,`Фраза показывает, что финансовое списание не устраняет экологический материал, поэтому потери публикуют рядом с урожаем.`]]}),a({slug:`language-returning-to-airwaves`,title:`A language returning to the airwaves`,topic:`community-language-revival`,genre:`sociolinguistic-radio-essay`,cefr:`B2+/C1`,paragraphs:[`When River Tongue Radio began broadcasting on Sunday mornings, its founders described the programme as a place for a minoritised language to be heard in ordinary public life. The language still had fluent older speakers, but decades of schooling and administration in the national language had narrowed where it was used. Ceremonies and songs survived more visibly than jokes about bus delays or arguments over football. Producer Ema Velez wanted the station to carry those unremarkable conversations, because a language confined to special occasions can be honoured and still remain socially fragile.`,`The first planning meetings exposed a difficult question: which form should presenters use? A recently published textbook offered consistent spelling and grammar, useful for learners. Yet speakers from upstream villages used different endings and rejected several vocabulary choices as unfamiliar. Choosing only the textbook form might make lessons easier while implying that living regional speech was defective. The team adopted a shared written guide for essential announcements but allowed presenters to speak their own varieties, identifying them without ranking one as the authentic centre.`,`This policy made live radio unpredictable. Listeners sometimes called to correct a word, only for another caller to defend it as common in a neighbouring valley. Ema refused to settle every disagreement instantly. Producers saved the clip, contacted several speakers and later broadcast a short segment explaining where competing forms were documented. When no clear history emerged, the archive retained the uncertainty. The point was not to make all claims equally true; it was to prevent the loudest first response from becoming a rule merely because radio moves quickly.`,`Young presenters brought another tension. They mixed River Tongue with the national language, especially when discussing gaming, climate protests or university life. Some elders heard this as evidence of decline. Linguist Pavel Ors argued that switching languages can also show active use: speakers choose resources suited to audience and topic. The station did not celebrate every borrowed word automatically. Instead, youth teams interviewed elders about older expressions, invented terms cautiously and tested whether listeners understood them without a long explanation.`,`One successful series followed the vocabulary of river work. A retired boat builder described tools while a teenager filmed his hands for the station website. The builder used two names for one wooden pin, depending on its position. An editor initially treated one as a mistake and nearly removed it. Video context showed that the distinction was systematic. The episode became a lesson in why collecting isolated word lists can flatten knowledge carried by action, material and place.`,`Audience numbers provide incomplete evidence of revival. Online plays rose sharply after clips gained subtitles in the national language, but many viewers were not learners. The station therefore tracks several signals: messages written in River Tongue, participation in conversation groups, requests from schools and new recordings contributed by families. None proves that a household has changed its daily language. Together they reveal whether broadcasting creates routes from passive recognition towards use, teaching and further documentation.`,`Funding brings questions of authority. A national cultural grant pays for equipment, while village associations nominate members to an editorial council. The grant requires financial reporting but does not select acceptable vocabulary. Ema publishes both arrangements because claims of community ownership become weak when money and decision-making remain obscure. Disagreement continues over airtime, pronunciation and political topics; the council’s role is to make the process accountable, not to pretend a language community naturally speaks with one voice.`,`River Tongue Radio has not reversed language shift, and its producers resist heroic accounts in which technology rescues what society abandoned. Broadcasting cannot replace teaching, family conversation or legal recognition. It can, however, widen the situations in which the language does real work and preserve evidence of variation without turning variation into disorder. Its achievement lies in making room for speakers to negotiate a shared future audibly—complete with hesitation, borrowing and correction—rather than presenting revival as the recovery of one pure voice from the past.`],questions:[[`detail`,`What everyday gap did Ema want the station to address?`,[`The language was rarely heard in everyday conversation`,`Older speakers had forgotten all ceremonial songs and stories`,`National radio refused to report football results from the valley`,`Schools lacked a consistent textbook spelling for beginners`],0,`Ceremonies and songs survived more visibly than jokes about bus delays or arguments over football.`,`Сопоставление церемоний с бытовыми шутками и спорами показывает нехватку языка именно в обычной современной публичной жизни.`],[`inference`,`Why was the textbook form not adopted as the only broadcast standard?`,[`Its spelling system could not be used for official announcements`,`Exclusive use could make regional living varieties seem inferior`,`Young presenters were unable to read any textbook vocabulary`,`The cultural grant prohibited consistent written grammar`],1,`Choosing only the textbook form might make lessons easier while implying that living regional speech was defective.`,`Противопоставление easier и defective показывает риск: удобная единая норма могла объявить живые региональные формы неправильными.`],[`purpose-attitude`,`Why did producers delay responses to disputed words?`,[`To discourage listeners from contributing corrections during broadcasts`,`To wait until the textbook authors supplied an official ruling`,`To investigate variation before accepting the quickest confident claim`,`To remove every uncertain expression from the public archive`],2,`to prevent the loudest first response from becoming a rule merely because radio moves quickly.`,`Формулировка прямо показывает цель задержки: скорость и уверенность первого звонка не должны автоматически создавать языковое правило.`],[`reference`,`What does “This policy” at the start of paragraph 3 refer to?`,[`Using only the national language for essential announcements`,`Asking textbook authors to rank every village variety`,`Recording ceremonies while avoiding contemporary conversation`,`Combining written guidance with multiple spoken varieties`],3,`The team adopted a shared written guide for essential announcements but allowed presenters to speak their own varieties`,`Предыдущее предложение формулирует политику сочетания общей письменной опоры с разными устными вариантами, на неё указывает This policy.`],[`vocabulary-context`,`What does “flatten” mean in the boat-builder example?`,[`Remove distinctions by reducing knowledge to a simple list`,`Translate practical terms into the national language for subtitles`,`Pronounce two regional words with the same speech sound`,`Place physical tools on a table before recording them`],0,`collecting isolated word lists can flatten knowledge carried by action, material and place.`,`Слова isolated word lists противопоставлены контексту действия и места, поэтому flatten означает обеднить знание, убрав значимые различия.`],[`main-idea`,`How does the station understand language revival?`,[`As restoring one uncontested historical form through broadcasting`,`As expanding real use while openly negotiating variation and authority`,`As maximising online views regardless of who watches clips`,`As replacing family speech and schooling with radio programmes`],1,`widen the situations in which the language does real work and preserve evidence of variation`,`Заключительная цитата показывает две главные задачи: расширять реальное употребление и сохранять вариативность без ложной унификации.`],[`inference`,`Why are several audience indicators tracked together?`,[`Family contributions are more accurate than conversation-group attendance`,`Schools require a single number before requesting any recordings`,`One online-play total cannot show whether recognition becomes active use`,`Financial reports must include messages written by every listener`],2,`None proves that a household has changed its daily language. Together they reveal whether broadcasting creates routes from passive recognition towards use`,`Слова None proves и Together reveal показывают, что отдельный показатель недостаточен, а совокупность отражает движение к активному употреблению.`]]}),a({slug:`weather-written-before-instruments`,title:`Weather written before instruments`,topic:`historical-climate-reconstruction`,genre:`archival-science-investigation`,cefr:`B2+/C1`,paragraphs:[`A modern weather station can produce thousands of measurements each day, but researchers studying earlier centuries face a quieter archive. They seek ship logbooks, harvest accounts, frozen-river dates and personal diaries. Survival is uneven: a careful record may have vanished while an accidental copy endured. None was created to answer today’s climate questions. Historical climatologist Inez Rao calls them “witnesses with other jobs”: each source noticed weather because it affected navigation, money, ritual or daily plans, and each ignored conditions that did not matter to its original writer.`,`Ship logs appear especially precise. Officers recorded wind direction, sea state and position at regular hours. Yet instruments, terminology and routes changed over time. Even the stated hour depended on shipboard timekeeping conventions that were not always identical. A word translated as “storm” might describe force differently in two navies, while ships avoided dangerous regions in some seasons. Researchers therefore study the instructions issued to officers and compare overlapping voyages. The neat handwriting is not treated as automatic accuracy; it is evidence produced within a changing professional system.`,`Phenological records—dates when plants flower or fruit ripens—offer another route. One estate kept its first-apple-blossom date for 140 years. The identity of the observer changed several times, although the recording instructions survived. The series seemed ideal until Inez discovered that the orchard moved downhill in 1882 and changed variety in 1910. Both decisions could shift flowering independently of temperature. Rather than discard the notebook, the team divided the series at those points and used nearby records to estimate how strongly location and variety altered the signal.`,`Diaries provide fine descriptions but uneven attention. A writer may mention a late frost because it ruined a picnic, then ignore three ordinary cold mornings. Travel, illness or a change of routine can alter attention without altering weather. Repeated silence does not mean repeated mild weather. Researchers code explicit observations and avoid turning absence of comment into a temperature value. When diarists record effects—closed roads, failed crops or clothing—they seek independent dates in newspapers and accounts, building a chain rather than resting a conclusion on one memorable sentence.`,`The project’s greatest challenge is combining sources without pretending they measure the same thing. River ice reflects accumulated cold, local flow and human changes to the banks. Grain prices respond to weather but also war, transport and policy. Each proxy is calibrated against periods where instrumental records overlap. Inez’s team uses models that represent these additional influences and produces a range of plausible temperatures rather than one exact figure. Wider ranges are not always weaker work; sometimes they are the most accurate description of limited evidence.`,`A surprising correction came from monastery bells. Historians had interpreted frequent “ice bell” payments as proof of severe winters, since the bells warned travellers near a frozen crossing. Account books later showed that one abbot paid a fixed winter allowance whether the bell rang or not. Only records naming individual ringing days could support weather reconstruction. The payment series remained valuable for labour history, illustrating how a source can be reliable and still answer the wrong question.`,`Digitisation has expanded access, but it introduces its own selection. Famous voyages and wealthy estates are scanned more often than routine coastal traffic or small farms. Optical text software struggles with old handwriting and may silently turn wind symbols into letters. The database displays original page images beside transcriptions and marks automated readings. Volunteers correct many errors, while uncertain marks remain searchable as uncertain rather than disappearing from the dataset.`,`Historical reconstruction does not replace direct modern measurement, nor does one diary prove a global trend. Its contribution is extension: carefully connected records can place recent conditions within a longer range of variation. Inez argues that transparency is more valuable than a smooth line. A reader should be able to see which source supports each period, what changed in its production and why the final estimate becomes more or less uncertain. The past speaks most clearly when researchers preserve its accents and silences.`],questions:[[`detail`,`Why does Inez call historical sources “witnesses with other jobs”?`,[`They were written by people who also operated weather stations`,`They recorded only conditions ordered by government scientists`,`Their authors travelled between several professional occupations`,`They observed weather for purposes unrelated to modern climate research`],3,`None was created to answer today’s climate questions.`,`Краткая цитата показывает, что источники возникли ради иных практических задач, а климатические сведения были побочным наблюдением.`],[`inference`,`Why are naval instructions studied alongside ship logs?`,[`To understand how recording practices shaped apparently precise entries`,`To calculate the wages paid to officers during dangerous voyages`,`To replace position records with translated storm vocabulary`,`To identify which ships carried orchard plants between countries`],0,`Researchers therefore study the instructions issued to officers and compare overlapping voyages.`,`Слово therefore связывает изучение инструкций с изменчивыми терминами и методами, показывая необходимость понять производство записей.`],[`purpose-attitude`,`Why was the orchard notebook divided into separate periods?`,[`Several years contained no explicit blossom date`,`Changes of location and variety could imitate a temperature effect`,`Nearby estates refused to share their comparable records`,`The notebook switched from handwriting to digital text`],1,`Both decisions could shift flowering independently of temperature.`,`Формулировка independently of temperature показывает, что перенос сада и смена сорта создавали иной сигнал, требующий разделения ряда.`],[`reference`,`What does “those points” in paragraph 3 refer to?`,[`The years when nearby weather stations began operating`,`The first and last dates recorded in the notebook`,`The orchard’s relocation and later change of apple variety`,`The temperature ranges estimated from other estates`],2,`the orchard moved downhill in 1882 and changed variety in 1910.`,`Предыдущее предложение называет два конкретных изменения и года, поэтому those points указывает на эти разрывы условий.`],[`vocabulary-context`,`What does “chain” mean in the diary discussion?`,[`A formula converting clothing descriptions into temperature`,`A physical barrier closing a road after frost`,`A continuous diary with no missing observations`,`A sequence of connected evidence from independent records`],3,`they seek independent dates in newspapers and accounts, building a chain rather than resting a conclusion on one memorable sentence.`,`Противопоставление independent dates и one sentence показывает, что chain означает связанную последовательность взаимно поддерживающих свидетельств из разных источников.`],[`main-idea`,`What principle guides the project’s treatment of uncertainty?`,[`Transparent ranges can represent limited evidence more honestly`,`One exact figure is preferable whenever sources disagree`,`Uncertain automated readings should be deleted from databases`,`Historical records become reliable only after complete digitisation`],0,`Wider ranges are not always weaker work; sometimes they are the most accurate description of limited evidence.`,`Цитата прямо показывает принцип: широкий диапазон может честнее и точнее отражать ограничения исторических свидетельств.`],[`inference`,`What lesson comes from the monastery payment records?`,[`Financial records are unsuitable for every historical investigation`,`A trustworthy record may be irrelevant to the inference being made`,`Winter bells were never actually used near frozen crossings`,`Labour history depends on reconstructing exact temperatures`],1,`a source can be reliable and still answer the wrong question.`,`Заключительная формулировка эпизода показывает вывод: достоверная выплата не обязательно свидетельствует о фактической погоде.`]]}),a({slug:`journey-home-for-storm-bird`,title:`A journey home for Storm Bird`,topic:`museum-object-restitution`,genre:`cultural-policy-case-analysis`,cefr:`B2+/C1`,paragraphs:[`For more than a century, a carved canoe prow known as Storm Bird stood in the central gallery of Harrington Museum. Its label celebrated the skill of makers from the distant Nalo Islands and stated that naval officer Edward Vale had “collected” it in 1904. A provenance researcher later opened Vale’s letters and found a less neutral account. The carving had been taken after colonial troops ordered a coastal village to surrender ceremonial objects. The museum held legal title under old documents, but the word collected no longer described the transaction honestly.`,`The Nalo Cultural Council requested the prow’s return. Its letter did not argue that all objects made on the islands must leave every foreign museum. It identified Storm Bird as a named ancestor object whose launch history was still recited, and included testimony from the families responsible for its care. Council members said display without those relationships turned the prow into an example of style while concealing obligations attached to who may move, repair or address it.`,`Harrington’s trustees initially proposed a high-resolution digital copy for the islands while retaining the original. They argued that the museum could guarantee stable humidity and offer millions of visitors access. The council welcomed digital documentation but rejected it as a substitute. A scan could support teaching and future repair, yet it could not participate in ceremonies or restore authority over the material object. Access, both sides gradually recognised, was not only a question of how many eyes could see something.`,`Conservation raised practical concerns that were genuine even when they were sometimes used to delay discussion. The prow contained old repairs, and the island cultural centre was still installing climate control. Conservators from both institutions examined the wood together and designed a travelling case. Nalo specialists explained which plant oils could be used and which marks should remain untouched. Their expertise altered the treatment plan rather than appearing only as cultural background beside a technical decision made elsewhere.`,`Public debate became polarised. Some commentators claimed return would empty museums; others suggested any hesitation proved bad faith. Director Miriam Hale resisted both predictions. Decisions, she said, require the history and status of a particular object, the authority of the requesting group and a feasible care plan. Case-by-case work is slower than a universal slogan, but it avoids treating every acquisition or every claim as identical. Consistency should lie in the questions asked and evidence published, not necessarily in one outcome.`,`The museum eventually transferred ownership to the Nalo Cultural Council. Storm Bird remained at Harrington for eight further months in a jointly written display about its removal and return. The label named the earlier coercion, included the museum’s previous wording and invited visitors to consider how language had shaped what they thought they saw. Then the prow travelled home accompanied by conservators and two Nalo apprentices who had participated in preparing the case.`,`Return did not end the relationship. The council chose to lend a newly commissioned sculpture to Harrington for five years, but under an agreement specifying interpretation, review dates and the artist’s right to withdraw it from display for a ceremonial visit. Translation costs and insurance were shared in advance. Some critics called this arrangement censorship. Miriam described it as accountable borrowing: the museum could present an important contemporary work without assuming that possession erased the maker’s continuing interests. The agreement made conditions visible before conflict arose.`,`Storm Bird is now housed in the Nalo centre and leaves storage for selected community occasions. Online visitors can explore the shared scan and a bilingual history assembled by both institutions. The case did not provide a simple formula for every collection, nor did return repair the violence of 1904. It changed who could decide the object’s future and forced Harrington to replace a comfortable story of acquisition with a documented one. Restitution, here, was less an act of deleting history than of redistributing authority within it.`],questions:[[`detail`,`What changed the understanding of how Storm Bird entered the museum?`,[`A new translation of the carving’s launch song`,`A scientific analysis of its earlier wooden repairs`,`Letters revealing coercion behind the supposed collection`,`A trustee’s discovery that legal title had expired`],2,`A provenance researcher later opened Vale’s letters and found a less neutral account. The carving had been taken after colonial troops ordered a coastal village to surrender ceremonial objects.`,`Письма не только дают less neutral account, но и прямо сообщают, что troops ordered villagers to surrender ceremonial objects, то есть раскрывают принуждение за словом collected.`],[`inference`,`Why did the Cultural Council describe the prow as a named ancestor object?`,[`To request that the museum remove every canoe from display`,`To claim that no island-made object could ever be shown abroad`,`To prove the original maker had signed a legal ownership document`,`To distinguish its obligations from a generic art example`],3,`display without those relationships turned the prow into an example of style while concealing obligations`,`Противопоставление relationships и example of style показывает, что статус предка подчёркивал обязанности и связи, скрытые эстетической витриной.`],[`purpose-attitude`,`Why was a digital copy considered insufficient?`,[`It could transmit information but not restore material and ceremonial authority`,`Its image quality was too low for educational or repair work`,`The museum refused to let island teachers use the digital files`,`It would expose confidential visitor numbers at Harrington`],0,`A scan could support teaching and future repair, yet it could not participate in ceremonies or restore authority over the material object.`,`Противопоставление could support и could not показывает границу копии: знания сохраняются, но материальная и церемониальная власть не возвращается.`],[`reference`,`What does “Their expertise” in paragraph 4 refer to?`,[`The trustees’ knowledge of international ownership law`,`Nalo specialists’ knowledge of appropriate care and meaningful marks`,`Journalists’ predictions about museums becoming empty`,`The conservators’ ability to build a travelling case alone`],1,`Nalo specialists explained which plant oils could be used and which marks should remain untouched.`,`Предыдущее предложение называет знания специалистов Нало об уходе и значимых следах, на них указывает Their expertise.`],[`vocabulary-context`,`What does “polarised” mean in the public-debate paragraph?`,[`Focused mainly on damage from cold storage conditions`,`Conducted privately between two groups of conservators`,`Divided into strongly opposed simplified positions`,`Resolved by applying one consistent legal formula`],2,`Some commentators claimed return would empty museums; others suggested any hesitation proved bad faith.`,`Две крайние противоположные формулировки показывают, что polarised означает раскол на жёстко противостоящие упрощённые позиции.`],[`main-idea`,`What principle is emphasised by the Storm Bird case?`,[`Legal ownership should settle all ethical questions automatically`,`Digital access is always more important than physical location`,`Every historical object requires precisely the same final decision`,`Transparent evidence and shared authority can reshape museum relationships`],3,`It changed who could decide the object’s future and forced Harrington to replace a comfortable story of acquisition with a documented one.`,`Цитата показывает оба главных изменения: перераспределение права решения и замену удобной версии прозрачной документированной историей.`],[`inference`,`Why is the later sculpture loan called “accountable borrowing”?`,[`Its conditions recognise continuing interests instead of assuming possession is absolute`,`It allows Harrington to display the work without naming its artist`,`Its five-year length prevents any ceremonial use on the islands`,`It transfers permanent ownership back to the foreign museum`],0,`the museum could present an important contemporary work without assuming that possession erased the maker’s continuing interests.`,`Формулировка without assuming показывает подотчётность займа: владение экспозицией не отменяет продолжающиеся права и интересы автора.`]]}),a({slug:`forest-that-listens-back`,title:`The forest that listens back`,topic:`ai-acoustic-conservation`,genre:`interdisciplinary-research-critique`,cefr:`B2+/C1`,paragraphs:[`Across the Luma Reserve, solar-powered recorders capture one minute of forest sound every ten minutes. The project began because human survey teams could visit each valley only a few times per year. Ecologist Noor Banerjee hoped automated analysis would reveal when rare frogs called and where chainsaws appeared near protected boundaries. She avoided saying the system “hears the forest.” Microphones register pressure changes, algorithms classify patterns and people decide what those classifications should mean for action.`,`The first frog model performed impressively in the laboratory. It had learned from clear recordings collected close to males during the breeding season. In the reserve, rain struck recorder cases, insects produced similar pulses and several frog species called together. Accuracy fell sharply. Instead of labelling the forest data noisy, Noor’s team recognised that the training collection was unusually clean. The apparent disorder belonged to the model’s limited experience, not to an ecosystem failing to provide tidy examples.`,`Researchers built a broader training set by asking field assistants to label short clips. Every clip was heard independently by two people; disagreements went to a specialist. The process was slow and labels still contained judgement, especially when a call was faint. Seasonal updates add newly encountered sound combinations instead of freezing the first taxonomy. The database records agreement and signal quality rather than presenting all examples as equally certain. Models can then be evaluated separately on clear, overlapping and distant calls, revealing where confidence actually comes from.`,`False alarms carry different costs. Sending a ranger to investigate a machine that is really heavy rain wastes scarce time. Missing an active chainsaw may allow serious damage. Rangers record what each visit actually finds, feeding outcomes back into evaluation. The team therefore does not use one probability threshold for every sound. Potential machinery receives a cautious threshold and rapid human review, while frog estimates are aggregated across nights before changing a population trend. Technical settings express priorities; they are not merely neutral mathematical details.`,`Recording also raises social questions. Several devices stand near paths used by neighbouring communities. Although the system is designed for wildlife, microphones may capture recognisable speech. The reserve posts locations, filters the human-voice range before uploads and allows community monitors to inspect deletion logs. Raw audio is kept briefly and access is restricted. Consent cannot be reduced to a sign at the gate, so the project reviews placement when people identify a route as private or culturally sensitive.`,`Open data creates another tension. Sharing frog detections helps outside scientists test the findings, but exact coordinates could guide collectors towards a rare species. Public files therefore use larger map cells and delayed dates, while approved researchers can request detailed data under conditions. This tiered approach frustrates those who equate openness with immediate unrestricted release. Noor argues that reproducibility requires enough evidence to inspect a claim, not necessarily publication of every location without regard to foreseeable harm.`,`The devices themselves have an environmental footprint. Batteries fail, solar panels require materials and field visits disturb trails. Repairable housings are preferred to sealed units when weather protection allows. The team publishes energy use and replaces recorders only when a clear research decision depends on the added coverage. One proposed expansion was cancelled after analysis showed that existing microphones already answered the corridor question. More data would have produced a smoother map, but not a different management choice; technical abundance was not treated as value in itself.`,`After five years, acoustic monitoring has extended observation across seasons and helped rangers identify two areas of repeated illegal cutting. It has not eliminated fieldwork. People verify alerts, study habitat and notice phenomena no classifier was built to recognise. Noor describes the system as an instrument within a relationship of judgement, labour and accountability. It becomes useful not when humans leave the loop, but when each participant—model, technician, resident and ecologist—has a visible role and the limits of automated inference remain open to challenge.`],questions:[[`detail`,`Why was acoustic monitoring introduced in the reserve?`,[`Local communities had requested constant recording of paths`,`Human teams could not observe every valley frequently enough`,`Laboratory frog recordings contained too much rainfall noise`,`Rangers wanted to replace every field visit with solar devices`],1,`human survey teams could visit each valley only a few times per year.`,`Цитата показывает исходное ограничение редких человеческих посещений, которое непрерывнее распределённые записи должны были дополнить.`],[`inference`,`What did poor reserve performance reveal about the first model?`,[`Forest frogs had changed their calls after the laboratory study`,`Recorder cases amplified every insect sound beyond recognition`,`Its clean training examples did not represent real sound mixtures`,`Field assistants had labelled all breeding-season calls incorrectly`],2,`the training collection was unusually clean. The apparent disorder belonged to the model’s limited experience`,`Слова unusually clean и limited experience показывают несоответствие обучающих примеров сложной реальной звуковой среде в заповеднике.`],[`purpose-attitude`,`Why are agreement and signal quality stored with clip labels?`,[`To make every uncertain example appear equally authoritative`,`To calculate payments for field assistants automatically`,`To remove specialists from disputed identification work`,`To expose uncertainty and test performance under different conditions`],3,`The database records agreement and signal quality rather than presenting all examples as equally certain.`,`Противопоставление rather than показывает цель метаданных: сохранять различия уверенности вместо ложного равенства всех подписей.`],[`reference`,`What does “they” refer to in “they are not merely neutral mathematical details”?`,[`Probability thresholds chosen for different sound categories`,`The human reviewers listening to possible machinery`,`The nights combined into a frog population estimate`,`The costs produced by missed chainsaw activity`],0,`The team therefore does not use one probability threshold for every sound.`,`Предыдущее предложение называет разные probability thresholds, поэтому местоимение they относится к этим техническим настройкам.`],[`vocabulary-context`,`What does “tiered” mean in the data-sharing paragraph?`,[`Stored on devices arranged at different forest heights`,`Organised into levels with different degrees of access`,`Ranked only by the rarity of detected frog species`,`Published through several competing research journals`],1,`Public files therefore use larger map cells and delayed dates, while approved researchers can request detailed data under conditions.`,`Сопоставление публичных обобщённых и одобренных подробных данных показывает, что tiered означает уровни доступа с разными условиями.`],[`main-idea`,`How does Noor characterise the role of automated monitoring?`,[`As a neutral replacement for human judgement and local knowledge`,`As a way to maximise data collection regardless of decisions`,`As one accountable instrument in a human-ecological system`,`As a classifier useful only for detecting illegal machinery`],2,`Noor describes the system as an instrument within a relationship of judgement, labour and accountability.`,`Цитата прямо определяет систему как один инструмент внутри отношений решения, труда и подотчётности, а не автономную замену людей.`],[`inference`,`Why was one proposed recorder expansion cancelled?`,[`Community monitors rejected every device near a public path`,`Solar panels could not supply enough power during winter`,`Detailed coordinates had already attracted rare-species collectors`,`Additional data would not have changed the relevant management decision`],3,`More data would have produced a smoother map, but not a different management choice`,`Противопоставление smoother map и not a different choice показывает, что дополнительное покрытие не влияло на практическое решение.`]]})]);export{o as READING_TASK12_18_SETS};